    /**
     * Parse a pasted JSON array of prompts, tolerating the extras an AI
     * model commonly adds: a ```json fence around it, or a sentence of
     * preamble/trailing commentary before or after the array itself.
     */
    function _extractJsonArray(raw) {
        let text = (raw || '').trim();
        const fenced = text.match(/```(?:json)?\s*\n([\s\S]*?)\n```/i);
        if (fenced) text = fenced[1].trim();
        try {
            const parsed = JSON.parse(text);
            if (Array.isArray(parsed)) return parsed;
        } catch {}
        const start = text.indexOf('[');
        const end = text.lastIndexOf(']');
        if (start !== -1 && end > start) {
            try {
                const parsed = JSON.parse(text.slice(start, end + 1));
                if (Array.isArray(parsed)) return parsed;
            } catch {}
        }
        return null;
    }

    function _switchImportFmt(fmt) {
        _importFmt = fmt;
        $$('.import-fmt-tab').forEach(t => t.classList.toggle('active', t.dataset.fmt === fmt));
        const panels = {
            json: '#importPanelJson',
            markdown: '#importPanelMarkdown',
            file: '#importPanelFile',
            template: '#importPanelTemplate',
            smart: '#importPanelSmart'
        };
        Object.entries(panels).forEach(([f, sel]) => {
            const el = $(sel);
            if (el) el.style.display = f === fmt ? '' : 'none';
        });
        // Populate the template panel when shown
        if (fmt === 'template') _renderImportTemplate();
    }

    /**
     * Parse Markdown into an array of prompt objects. A new "#" or "##"
     * heading always starts a new prompt (an explicit "---" also forces a
     * break, for a stray top-level heading with no body of its own -- e.g.
     * a "# Board Name" line above several "## Prompt Title" prompts -- so
     * neither "---" nor a fixed heading level is required from the AI).
     * Recognised per-prompt fields, each optional except the title:
     *   ## Title
     *   > One-line outcome                  (or *italic description*)
     *   Categories: cat1, cat2              (bold **Categories:** also works)
     *   Tags: tag1, tag2                    (bold **Tags:** also works)
     *   Everything else non-blank is the prompt body, verbatim. A ``` fence
     *   around the body is accepted but not required; content inside a
     *   fence is never re-parsed as a heading/field so real code (e.g. a
     *   Python "#" comment) can't be mistaken for a new prompt.
     */
    function _stripOuterFence(md) {
        const trimmed = md.trim();
        const m = trimmed.match(/^```[a-zA-Z]*\n([\s\S]*)\n```$/);
        return m ? m[1] : md;
    }

    function parseMarkdownImport(md) {
        const prompts = [];
        const lines = _stripOuterFence(md).replace(/\r\n/g, '\n').split('\n');
        let current = null;
        let inCode = false;

        function flush() {
            if (current) {
                const content = current.contentLines.join('\n').trim();
                if (current.title && content) {
                    prompts.push({
                        title: current.title,
                        description: current.description,
                        content,
                        categories: current.categories,
                        tags: current.tags
                    });
                }
            }
            current = null;
        }

        for (const line of lines) {
            const trimmed = line.trim();

            if (/^```/.test(trimmed)) {
                inCode = !inCode;
                continue;
            }
            if (inCode) {
                if (current) current.contentLines.push(line);
                continue;
            }
            if (/^#{1,2}\s+/.test(line)) {
                flush();
                current = {
                    title: line.replace(/^#{1,2}\s+/, '').trim(),
                    description: '',
                    categories: '',
                    tags: '',
                    contentLines: []
                };
                continue;
            }
            if (/^[-=]{3,}$/.test(trimmed)) {
                flush();
                continue;
            }
            if (!current) continue; // preamble before the first heading -- ignore
            if (!current.description && /^\*[^*].*[^*]\*$/.test(trimmed)) {
                current.description = trimmed.replace(/^\*|\*$/g, '').trim();
                continue;
            }
            if (!current.description && /^>\s?/.test(trimmed)) {
                current.description = trimmed.replace(/^>\s?/, '').trim();
                continue;
            }
            if (/^(\*\*Categories\*\*:|\*\*Categories:\*\*|Categories:)/i.test(trimmed)) {
                current.categories = trimmed.replace(/^(\*\*Categories\*\*:|\*\*Categories:\*\*|Categories:)/i, '').trim();
                continue;
            }
            if (/^(\*\*Tags\*\*:|\*\*Tags:\*\*|Tags:)/i.test(trimmed)) {
                current.tags = trimmed.replace(/^(\*\*Tags\*\*:|\*\*Tags:\*\*|Tags:)/i, '').trim();
                continue;
            }
            current.contentLines.push(line);
        }
        flush();
        return prompts;
    }

    async function _doImportToVault(prompts) {
        const vaultId = state.librarySource.vaultId;
        const folderPath = state.vaultBrowsePath || '';
        let imported = 0;
        let failed = 0;
        for (const p of prompts) {
            if (!p || !p.title) {
                failed++;
                continue;
            }
            try {
                await api(`/vaults/${vaultId}/prompts`, {
                    method: 'POST',
                    body: {
                        title: p.title,
                        content: p.content || '',
                        categories: Array.isArray(p.categories) ? p.categories.join(', ') : (p.categories || ''),
                        tags: Array.isArray(p.tags) ? p.tags.join(', ') : (p.tags || ''),
                        path: folderPath
                    }
                });
                imported++;
            } catch {
                failed++;
            }
        }
        closeImportModal();
        await loadPrompts();
        if (failed) {
            toast(`Imported ${imported} prompt${imported !== 1 ? 's' : ''}, ${failed} failed`, imported ? 'warning' : 'error');
        } else {
            toast(`Imported ${imported} prompt${imported !== 1 ? 's' : ''}`, 'success');
        }
    }

    async function _doImport(prompts) {
        if (!Array.isArray(prompts) || !prompts.length) {
            toast('No valid prompts found to import', 'warning');
            return;
        }
        if (state.librarySource && state.librarySource.type === 'vault') {
            await _doImportToVault(prompts);
            return;
        }
        const result = await api('/import', {
            method: 'POST',
            body: {
                prompts
            }
        });
        closeImportModal();
        await loadPrompts();
        await loadFilterOptions();
        toast(`Imported ${result.imported || prompts.length} prompt${prompts.length !== 1 ? 's' : ''}`, 'success');
    }

    async function handleImport(e) {
        e.preventDefault();
        try {
            if (_importFmt === 'json') {
                const raw = $('#importContent').value.trim();
                const prompts = _extractJsonArray(raw);
                if (!prompts) {
                    toast('Invalid JSON — paste an array of prompt objects', 'warning');
                    return;
                }
                await _doImport(_applyBatchFolder(prompts));

            } else if (_importFmt === 'markdown') {
                const raw = $('#importMdContent').value.trim();
                if (!raw) {
                    toast('Paste some Markdown to import', 'warning');
                    return;
                }
                const prompts = parseMarkdownImport(raw);
                await _doImport(_applyBatchFolder(prompts));

            } else if (_importFmt === 'file') {
                const fileInput = $('#importFileInput');
                const file = fileInput?.files?.[0];
                if (!file) {
                    toast('Choose a file first', 'warning');
                    return;
                }
                const text = await file.text();
                let prompts;
                if (file.name.endsWith('.json')) {
                    prompts = _extractJsonArray(text);
                    if (!prompts) {
                        toast('Invalid JSON file', 'warning');
                        return;
                    }
                } else {
                    // Markdown file
                    prompts = parseMarkdownImport(text);
                }
                await _doImport(_applyBatchFolder(prompts));

            } else if (_importFmt === 'smart') {
                const rows = $$('#smartPasteResults .smart-paste-item').filter(row => row.querySelector('.smart-paste-include').checked);
                if (!rows.length) {
                    toast('No prompts selected to import', 'warning');
                    return;
                }
                const prompts = rows.map(row => ({
                    title: row.querySelector('.smart-paste-title').value.trim(),
                    content: row.dataset.content
                }));
                await _doImport(_applyBatchFolder(prompts));
            }
        } catch (err) {
            console.error('import error:', err);
            toast('Import failed — check the format', 'error');
        }
    }

    function openExportModal() {
        $('#exportModal').classList.add('active');
    }

    function closeExportModal() {
        $('#exportModal').classList.remove('active');
    }

    // Vault sources have no DB-backed export routes — build export content
    // client-side from the already-loaded vault prompts instead.
    function _vaultExportRows() {
        return (state.prompts || []).map(p => ({
            title: p.title || '',
            description: p.description || '',
            content: p.content || '',
            categories: p.categories || [],
            tags: p.tags || [],
        }));
    }

    function _vaultExportMarkdown() {
        const lines = ['# Prompt Library Export\n', `*Exported: ${new Date().toLocaleString()}*\n\n---\n`];
        _vaultExportRows().forEach(p => {
            lines.push(`## ${p.title}\n`);
            if (p.description) lines.push(`*${p.description}*\n`);
            if (p.categories.length) lines.push(`**Categories:** ${p.categories.join(', ')}\n`);
            if (p.tags.length) lines.push(`**Tags:** ${p.tags.join(', ')}\n`);
            lines.push(`\n\`\`\`\n${p.content}\n\`\`\`\n\n---\n`);
        });
        return lines.join('\n');
    }

    function _vaultExportCsv() {
        const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
        const lines = [['title', 'description', 'content', 'categories', 'tags'].join(',')];
        _vaultExportRows().forEach(p => {
            lines.push([p.title, p.description, p.content, p.categories.join(';'), p.tags.join(';')].map(esc).join(','));
        });
        return lines.join('\n');
    }

    async function exportJson() {
        try {
            const isVault = state.librarySource && state.librarySource.type === 'vault';
            const data = isVault ? _vaultExportRows() : await api('/export');
            const filename = `prompts-${new Date().toISOString().slice(0, 10)}.json`;
            const content = JSON.stringify(data, null, 2);
            const res = await fetch('/api/save-file', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    filename,
                    content,
                    mime: 'application/json'
                }),
            });
            const result = await res.json();
            if (result.saved) {
                toast(`Saved to ${result.path}`, 'success');
                closeExportModal();
            } else if (result.error) {
                toast('Save failed: ' + result.error, 'error');
            }
            // If result.saved === false and no error, user cancelled — do nothing
        } catch (err) {
            toast('Could not export', 'error');
        }
    }

    async function exportFormat(path, mime, ext) {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const isVault = state.librarySource && state.librarySource.type === 'vault';
        if (isVault && ext === 'zip') {
            toast('Bulk ZIP export is for My Library only — switch sources to use it', 'warning');
            return;
        }
        try {
            const filename = `prompts-${new Date().toISOString().slice(0, 10)}.${ext}`;
            let content;
            if (isVault) {
                content = ext === 'csv' ? _vaultExportCsv() : _vaultExportMarkdown();
            } else {
                const res = await fetch(API_BASE + path);
                if (!res.ok) throw new Error();
                if (mime === 'application/zip') {
                    // Encode binary as base64 for JSON transport
                    const buf = await res.arrayBuffer();
                    const bytes = new Uint8Array(buf);
                    let bin = '';
                    bytes.forEach(b => {
                        bin += String.fromCharCode(b);
                    });
                    content = btoa(bin);
                } else {
                    content = await res.text();
                }
            }

            const saveRes = await fetch('/api/save-file', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    filename,
                    content,
                    mime
                }),
            });
            const result = await saveRes.json();
            if (result.saved) {
                toast(`Saved to ${result.path}`, 'success');
                closeExportModal();
            } else if (result.error) {
                toast('Save failed: ' + result.error, 'error');
            }
        } catch (err) {
            toast('Could not export', 'error');
        }
    }

    function triggerDownload(blob, filename) {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        a.click();
        URL.revokeObjectURL(url);
    }

