    // Shared helper: always escape folder/workspace views before applying a filter pill
    function _escapeToLibrary() {
        // Close any open workspaces
        ['#forgeWorkspace', '#labWorkspace', '#rolesWorkspace', '#playgroundWorkspace',
            '#chainWorkspace', '#metaPromptingWorkspace', '#contextBankWorkspace', '#componentsWorkspace',
            '#optimizerWorkspace', '#genWorkspace', '#dashboardWorkspace', '#workspacesLauncher', '#fillWorkspace', '#auditWorkspace', '#diffWorkspace',
            '#costWorkspace', '#pulseWorkspace', '#xrayWorkspace', '#spliceWorkspace', '#forkWorkstation',
            '#batchWorkspace', '#boardWorkspace', '#taxonomyWorkspace', '#versionWorkspace', '#backupWorkspace',
            '#exampleWorkspace', '#adapterWorkspace', '#evalWorkspace', '#compareWorkspace', '#historyWorkspace', '#lockWorkspace', '#integrityWorkspace', '#credentialsWorkspace', '#simplifyWorkspace', '#toneWorkspace', '#translateWorkspace', '#gauntletWorkspace',
            '#promptIdeWorkspace', '#promptForkingWorkspace',
        ].forEach(sel => {
            const el = $(sel);
            if (el && el.classList.contains('open')) el.classList.remove('open');
        });
        state.view = 'library';
        state.search = '';
        state.detailId = null;
        closeDetailPanel();
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'library'));
        $$('.folder-item').forEach(el => el.classList.remove('active'));
        const titleEl = $('#viewTitle');
        if (titleEl) titleEl.textContent = 'Library';
        const bcEl = $('#breadcrumb');
        if (bcEl) bcEl.innerHTML = '';
        const fvaEl = $('#folderViewActions');
        if (fvaEl) fvaEl.style.display = 'none';
    }

    window.PL_filterByCategory = function(value) {
        _escapeToLibrary();
        setFilterPill({
            type: 'category',
            value
        });
        // Highlight active sidebar item
        $$('[data-filter-cat]').forEach(el => {
            el.classList.toggle('active', el.dataset.filterCat === value);
        });
    };
    window.PL_filterByTag = function(value) {
        _escapeToLibrary();
        setFilterPill({
            type: 'tag',
            value
        });
        $$('[data-filter-tag]').forEach(el => {
            el.classList.toggle('active', el.dataset.filterTag === value);
        });
    };
