    /* ============================================================================
       PROMPT OPTIMIZER WORKSPACE
       ============================================================================ */

    const _optState = {
        selectedFrameworks: new Set(),
        selectedTechniques: new Map(),
        history: [],
        selectedForCompare: [],
        currentOutput: ''
    };

    window.openOptimizerWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        $('#optimizerWorkspace')?.classList.add('open');
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'optimizer'));
        setTimeout(() => $('#optPromptInput')?.focus(), 80);
    };

    function closeOptimizerWorkspace() {
        $('#optimizerWorkspace')?.classList.remove('open');
        $$('.nav-item[data-view]').forEach(el =>
            el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function _optSetScore(overall) {
        const ring = $('#optRingFill');
        const numEl = $('#optScoreNum');
        if (ring) ring.style.strokeDashoffset = String(226 - (overall / 100) * 226);
        if (numEl) numEl.textContent = overall;
        const spread = () => Math.max(55, overall - Math.floor(Math.random() * 12));
        const setM = (id, val) => {
            const el = $('#' + id);
            if (el) el.textContent = val + '%';
        };
        setM('optClarity', spread());
        setM('optSpecificity', spread());
        setM('optContext', spread());
        setM('optStructure', spread());
        setM('optActionability', spread());
    }

    function _optAddHistory(type, prompt, output, score) {
        _optState.history.unshift({
            id: Date.now(),
            type,
            prompt: prompt.substring(0, 80) + (prompt.length > 80 ? '...' : ''),
            output,
            score,
            timestamp: new Date().toLocaleTimeString()
        });
        if (_optState.history.length > 12) _optState.history.pop();
        _optRenderHistory();
    }

    function _optRenderHistory() {
        const el = $('#optHistory');
        if (!el) return;
        if (!_optState.history.length) {
            el.innerHTML = '<span class="hint" style="font-size:var(--fs-xs);">Run Optimize or Analyze to build history.</span>';
            return;
        }
        el.innerHTML = '';
        _optState.history.forEach(item => {
            const div = document.createElement('div');
            div.className = 'opt-history-item' + (_optState.selectedForCompare.includes(item.id) ? ' selected' : '');
            div.dataset.hid = item.id;
            div.innerHTML = '<div class="opt-history-preview">' + escapeHtml(item.prompt) + '</div>' +
                '<div class="opt-history-meta">' + item.type + ' · score ' + item.score + ' · ' + item.timestamp + '</div>';
            div.addEventListener('click', () => _optSelectHistory(item.id));
            el.appendChild(div);
        });
    }

    function _optSelectHistory(id) {
        const item = _optState.history.find(h => h.id === id);
        if (!item) return;
        const idx = _optState.selectedForCompare.indexOf(id);
        if (idx === -1) {
            if (_optState.selectedForCompare.length >= 2) _optState.selectedForCompare.shift();
            _optState.selectedForCompare.push(id);
        } else {
            _optState.selectedForCompare.splice(idx, 1);
        }
        _optRenderHistory();
        _optRenderCompare();
        const out = $('#optOutput');
        if (out) {
            out.textContent = item.output;
        }
        _optState.currentOutput = item.output;
        const actions = $('#optOutputActions');
        if (actions) actions.style.display = 'flex';
    }

    function _optRenderCompare() {
        const el = $('#optComparePanel');
        if (!el) return;
        const ids = _optState.selectedForCompare;
        if (ids.length < 2) {
            el.innerHTML = ids.length === 1 ?
                '<span class="hint" style="font-size:var(--fs-xs);">Select one more history item to compare.</span>' :
                '<span class="hint" style="font-size:var(--fs-xs);">Select two history items to compare.</span>';
            return;
        }
        const [a, b] = ids.map(id => _optState.history.find(h => h.id === id));
        el.innerHTML =
            '<div class="opt-compare-label">Version A · score ' + a.score + '</div>' +
            '<div class="opt-compare-block">' + escapeHtml(a.output) + '</div>' +
            '<div class="opt-compare-label">Version B · score ' + b.score + '</div>' +
            '<div class="opt-compare-block">' + escapeHtml(b.output) + '</div>';
    }

    async function _optRunOptimize() {
        const prompt = $('#optPromptInput')?.value?.trim();
        if (!prompt) {
            toast('Paste a prompt first', 'warning');
            return;
        }
        const frameworks = Array.from(_optState.selectedFrameworks).join(', ');
        const techniques = Array.from(_optState.selectedTechniques.entries())
            .map(([t, lvl]) => lvl > 1 ? t + ' (emphasis ×' + lvl + ')' : t).join(', ');
        const custom = $('#optCustomInstructions')?.value?.trim();
        const goal = $('#optGoalInput')?.value?.trim();
        const sys = 'You are an expert prompt engineer optimizing AI assistant prompts. Analyze the given prompt and return:\n\n1. OPTIMIZED PROMPT — rewrite for clarity, specificity, and output quality\n2. KEY IMPROVEMENTS — 3-5 specific changes and their impact\n3. WHY THESE WORK — brief explanation of optimization principles applied\n\nOptimize for: clarity (remove ambiguity), task specificity (narrow scope), instruction completeness (edge cases covered), and output usefulness (what the user actually needs).\n\nDO NOT add unnecessary length. DO NOT change the prompt\'s intent. DO NOT assume context the original doesn\'t provide.\n\nSCORE: [1-100] where 50 = no improvement, 70 = clear gains, 90 = production-ready, 100 = exemplary. Justify in one sentence.\n\nPlain text only, no markdown.';
        let usr = 'Optimize this prompt:\n\n"' + prompt + '"\n\n';
        if (frameworks) usr += 'Apply frameworks: ' + frameworks + '.\n';
        if (techniques) usr += 'Enhance with techniques: ' + techniques + '.\n';
        if (goal) usr += 'Intended outcome / goal: ' + goal + '.\n';
        if (custom) usr += 'Additional requirements: ' + custom + '.\n';
        const out = $('#optOutput');
        if (out) out.innerHTML = '<span class="hint">⏳ Optimizing…</span>';
        const result = await callAI(sys, usr, 1800);
        const scoreMatch = result.match(/SCORE:\s*(\d{1,3})/i);
        const score = scoreMatch ? Math.min(100, parseInt(scoreMatch[1])) : 75;
        const clean = scoreMatch ? result.slice(0, result.lastIndexOf('SCORE:')).trim() : result;
        if (out) out.textContent = clean;
        _optState.currentOutput = clean;
        const actions = $('#optOutputActions');
        if (actions) actions.style.display = 'flex';
        _optSetScore(Math.min(95, score + 5));
        _optAddHistory('optimize', prompt, clean, score);
        toast('Prompt optimized', 'success');
    }

    async function _optRunAnalyze() {
        const prompt = $('#optPromptInput')?.value?.trim();
        if (!prompt) {
            toast('Paste a prompt first', 'warning');
            return;
        }
        const custom = $('#optCustomInstructions')?.value?.trim();
        const goal = $('#optGoalInput')?.value?.trim();
        const sys = 'You are a World Class SSS expert prompt engineer, your specialty is analyzing and improving prompts. Analyze the given prompt and provide: 1. Overall quality score (1-100) 2. Strengths 3. Areas for improvement 4. Enhancement suggestions. End with SCORE: [number].';
        let usr = 'Analyze this prompt:\n\n"' + prompt + '"';
        if (goal) usr += '\n\nIntended outcome / goal: ' + goal;
        if (custom) usr += '\n\nConsider: ' + custom;
        const out = $('#optOutput');
        if (out) out.innerHTML = '<span class="hint">⏳ Analyzing…</span>';
        const result = await callAI(sys, usr, 1500);
        const scoreMatch = result.match(/SCORE:\s*(\d{1,3})/i);
        const score = scoreMatch ? Math.min(100, parseInt(scoreMatch[1])) : 70;
        const clean = scoreMatch ? result.slice(0, result.lastIndexOf('SCORE:')).trim() : result;
        if (out) out.textContent = clean;
        _optState.currentOutput = clean;
        const actions = $('#optOutputActions');
        if (actions) actions.style.display = 'flex';
        _optSetScore(score);
        _optAddHistory('analyze', prompt, clean, score);
        toast('Analysis complete', 'success');
    }

    function initOptimizerWorkspace() {
        const ws = $('#optimizerWorkspace');
        if (!ws) return;

        $$('#optimizerWorkspace .opt-fw-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const fw = this.dataset.fw;
                if (_optState.selectedFrameworks.has(fw)) {
                    _optState.selectedFrameworks.delete(fw);
                    this.classList.remove('active');
                } else {
                    _optState.selectedFrameworks.add(fw);
                    this.classList.add('active');
                }
            });
        });

        $$('#optimizerWorkspace .opt-tech-btn').forEach(btn => {
            btn.dataset.label = btn.textContent;
            btn.addEventListener('click', function() {
                const tech = this.dataset.tech;
                const lbl = this.dataset.label;
                const cur = _optState.selectedTechniques.get(tech) || 0;
                if (cur >= 24) {
                    _optState.selectedTechniques.delete(tech);
                    this.classList.remove('active');
                    this.removeAttribute('data-level');
                    this.textContent = lbl;
                } else {
                    const next = cur + 1;
                    _optState.selectedTechniques.set(tech, next);
                    this.classList.add('active');
                    this.dataset.level = next;
                    this.textContent = lbl + ' ×' + next;
                }
            });
        });

        $('#optSelectAllTechBtn')?.addEventListener('click', () => {
            $$('#optimizerWorkspace .opt-tech-btn').forEach(btn => {
                _optState.selectedTechniques.set(btn.dataset.tech, 1);
                btn.classList.add('active');
                btn.dataset.level = '1';
                btn.textContent = btn.dataset.label + ' ×1';
            });
        });
        $('#optClearTechBtn')?.addEventListener('click', () => {
            _optState.selectedTechniques.clear();
            $$('#optimizerWorkspace .opt-tech-btn').forEach(btn => {
                btn.classList.remove('active');
                btn.removeAttribute('data-level');
                btn.textContent = btn.dataset.label;
            });
        });

        $('#optOptimizeBtn')?.addEventListener('click', async function() {
            this.disabled = true;
            this.innerHTML = '<span class="material-symbols-outlined" style="animation:spin 1s linear infinite">progress_activity</span> Optimizing…';
            try {
                await _optRunOptimize();
            } catch (err) {
                const out = $('#optOutput');
                if (out) out.innerHTML = '<span class="hint">Error: ' + escapeHtml(err.message) + '</span>';
                toast('Optimization failed: ' + err.message, 'error');
            } finally {
                this.disabled = false;
                this.innerHTML = '<span class="material-symbols-outlined">rocket_launch</span> Optimize';
            }
        });

        $('#optAnalyzeBtn')?.addEventListener('click', async function() {
            this.disabled = true;
            this.innerHTML = '<span class="material-symbols-outlined" style="animation:spin 1s linear infinite">progress_activity</span> Analyzing…';
            try {
                await _optRunAnalyze();
            } catch (err) {
                const out = $('#optOutput');
                if (out) out.innerHTML = '<span class="hint">Error: ' + escapeHtml(err.message) + '</span>';
                toast('Analysis failed: ' + err.message, 'error');
            } finally {
                this.disabled = false;
                this.innerHTML = '<span class="material-symbols-outlined">analytics</span> Analyze';
            }
        });

        $('#optCopyBtn')?.addEventListener('click', async () => {
            const text = _optState.currentOutput || $('#optOutput')?.textContent?.trim();
            if (!text) return;
            if (await copyToClipboard(text)) toast('Output copied', 'success');
        });

        $('#optSaveBtn')?.addEventListener('click', async () => {
            if (!_optState.currentOutput) {
                toast('Optimize a prompt first', 'warning');
                return;
            }
            const raw = $('#optPromptInput')?.value?.trim() || '';
            const title = (raw.split(' ').slice(0, 6).join(' ') || 'Optimized prompt') + ' (opt)';
            try {
                const result = await api('/prompts', {
                    method: 'POST',
                    body: {
                        title,
                        content: _optState.currentOutput,
                        description: 'Optimized via Prompt Optimizer workspace',
                        categories: 'Prompt Engineering',
                        tags: 'optimized'
                    }
                });
                await loadPrompts();
                await loadFilterOptions();
                toast('Saved: ' + title, 'success');
                closeOptimizerWorkspace();
                if (result?.id) setTimeout(() => openDetail(result.id), 200);
            } catch {
                toast('Could not save', 'error');
            }
        });

        $('#closeOptimizerBtn')?.addEventListener('click', closeOptimizerWorkspace);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeOptimizerWorkspace();
        });
    }

    /* ============================================================================
       WORKSPACE SUITE — shared helpers
       Used by Quick Fill, Auditor, Diff Lens, Cost Lens, Pulse, X-Ray, Splicer.
       ============================================================================ */

    // Fill a <select> with library prompts. Keeps first option as placeholder.
    async function _wsFillPromptPicker(selectSel) {
        const sel = $(selectSel);
        if (!sel) return;
        try {
            const data = await api('/prompts');
            const list = Array.isArray(data) ? data : (data.prompts || []);
            const first = sel.options[0] ? sel.options[0].outerHTML : '<option value="">Load from library…</option>';
            sel.innerHTML = first + list.map(p =>
                '<option value="' + escapeAttr(p.id) + '">' + escapeHtml(p.title || 'Untitled') + '</option>').join('');
            sel._promptCache = list;
        } catch {
            /* picker stays empty — paste still works */
        }
    }

    function _wsPickedPrompt(selectSel) {
        const sel = $(selectSel);
        if (!sel || !sel.value || !sel._promptCache) return null;
        return sel._promptCache.find(p => String(p.id) === String(sel.value)) || null;
    }

    // Offer to replace the prompt a workspace result came from, or save it as a
    // new prompt. `sourcePrompt` must be the full cached object from
    // _wsPickedPrompt() (not just an id) so a replace can carry over every
    // existing field via PUT — the backend's PUT expects a full prompt payload.
    async function _wsSaveOrReplace({ text, sourcePrompt, newTitle, description, tags, extraNote }) {
        if (sourcePrompt) {
            const replace = confirm(
                'Replace the original prompt "' + sourcePrompt.title + '" with this result?\n\n' +
                'Cancel to save as a new prompt instead.'
            );
            if (replace) {
                const priorNotes = sourcePrompt.notes || '';
                const notes = (extraNote && priorNotes.endsWith(extraNote))
                    ? priorNotes
                    : [priorNotes, extraNote].filter(Boolean).join('\n');
                const existingTags = Array.isArray(sourcePrompt.tags) ? sourcePrompt.tags.join(',') : (sourcePrompt.tags || '');
                const mergedTags = Array.from(new Set(
                    (existingTags ? existingTags + ',' + tags : tags)
                        .split(',')
                        .map(t => t.trim())
                        .filter(Boolean)
                )).join(',');
                try {
                    await api('/prompts/' + sourcePrompt.id, {
                        method: 'PUT',
                        body: {
                            ...sourcePrompt,
                            content: text,
                            notes,
                            tags: mergedTags,
                        }
                    });
                    await loadPrompts();
                    await loadFilterOptions();
                    toast('Updated: ' + sourcePrompt.title, 'success');
                    return { id: sourcePrompt.id, replaced: true };
                } catch {
                    toast('Could not update prompt', 'error');
                    return null;
                }
            }
        }
        try {
            const result = await api('/prompts', {
                method: 'POST',
                body: {
                    title: newTitle,
                    content: text,
                    description,
                    categories: 'Prompt Engineering',
                    tags,
                    notes: extraNote || '',
                }
            });
            await loadPrompts();
            await loadFilterOptions();
            toast('Saved: ' + newTitle, 'success');
            return { id: result?.id, replaced: false };
        } catch {
            toast('Could not save', 'error');
            return null;
        }
    }

    // Rough token estimate — average of chars/4 and words*1.33 heuristics.
    function _wsEstTokens(text) {
        const t = text || '';
        const words = (t.trim().match(/\S+/g) || []).length;
        return Math.max(0, Math.round((t.length / 4 + words * 1.33) / 2));
    }

    // Classify prompt lines into structural components. Offline, keyword-scored.
    // Returns { role, context, task, constraints, format, examples, other } — arrays of lines.
    function _wsSplitComponents(text) {
        const out = {
            role: [],
            context: [],
            task: [],
            constraints: [],
            format: [],
            examples: [],
            other: []
        };
        const RX = {
            role: /\b(you are|act as|act like|adopt the|persona of|role of|behave as|you're an?|assume the role)\b/i,
            constraints: /\b(don'?t|do not|never|avoid|must not|no more than|at most|at least|limit(?:ed)? to|only|exclude|without|refuse|forbidden|not allowed)\b/i,
            format: /\b(format|bullet|bulleted|numbered list|table|json|xml|yaml|markdown|heading|word count|words? max|paragraphs?|respond in|output.{0,12}(as|in)|structure your|tone[:\s]|begin with|end with|no preamble)\b/i,
            examples: /\b(example|e\.g\.|for instance|for example|such as|input:|output:|sample)\b/i,
            task: /\b(write|create|generate|analy[sz]e|summari[sz]e|list|explain|rewrite|classify|extract|translate|design|draft|produce|evaluate|compare|review|identify|describe|outline|build|compose|convert|improve|suggest|recommend|brainstorm|critique|answer|research)\b/i,
            context: /\b(context|background|given|about|we are|our company|the user|scenario|situation|currently|working on|audience|reader)\b/i,
        };
        const lines = (text || '').split(/\n+/).map(l => l.trim()).filter(Boolean);
        lines.forEach((line, i) => {
            // Score each bucket; first-line role bias, early-line context bias.
            const scores = {
                role: (RX.role.test(line) ? 3 : 0) + (i === 0 ? 1 : 0),
                constraints: RX.constraints.test(line) ? 2.5 : 0,
                format: RX.format.test(line) ? 2.5 : 0,
                examples: RX.examples.test(line) ? 2 : 0,
                task: (RX.task.test(line) ? 2 : 0),
                context: (RX.context.test(line) ? 1.5 : 0) + (i > 0 && i < 3 ? 0.5 : 0),
            };
            let best = 'other',
                bestScore = 1; // below 1 → other
            Object.keys(scores).forEach(k => {
                if (scores[k] > bestScore) {
                    best = k;
                    bestScore = scores[k];
                }
            });
            out[best].push(line);
        });
        return out;
    }

    /* ============================================================================
       QUICK FILL WORKSPACE
       Pick or paste a template, auto-detect [placeholders] and {{variables}},
       fill them in a generated form, copy or save the result. Values are
       remembered per variable name in localStorage (pl_qf_memory).
       data-view="fill" | openFillWorkspace() | initFillWorkspace()
       ============================================================================ */

    const QF_MEM_KEY = 'pl_qf_memory';
    let _qfVars = []; // [{ token, name }]

    function _qfMemory() {
        try {
            return JSON.parse(localStorage.getItem(QF_MEM_KEY) || '{}');
        } catch {
            return {};
        }
    }

    // Legacy entries were a plain string value; normalize both shapes to {value, type}.
    function _qfMemGet(name) {
        const entry = _qfMemory()[name];
        if (entry == null) return { value: '', type: undefined };
        if (typeof entry === 'string') return { value: entry, type: undefined };
        return { value: entry.value || '', type: entry.type };
    }

    function _qfRemember(vals) {
        const mem = _qfMemory();
        Object.assign(mem, vals);
        const keys = Object.keys(mem);
        if (keys.length > 200) keys.slice(0, keys.length - 200).forEach(k => delete mem[k]);
        localStorage.setItem(QF_MEM_KEY, JSON.stringify(mem));
    }

    function _qfExtractVars(text) {
        const seen = new Set();
        const vars = [];
        const re = /\{\{([^{}\n]{1,60}?)\}\}|\[([^\[\]\n]{1,60}?)\]/g;
        let m;
        while ((m = re.exec(text || '')) !== null) {
            const token = m[0];
            if (seen.has(token)) continue;
            seen.add(token);
            vars.push({
                token,
                name: (m[1] || m[2] || '').trim()
            });
        }
        return vars;
    }

    function _qfWords(name) {
        return (name || '')
            .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2')
            .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
            .split(/[^a-zA-Z0-9]+/)
            .map(w => w.toLowerCase())
            .filter(Boolean);
    }

    function _qfGuessType(name) {
        const words = _qfWords(name);
        const has = (...keys) => keys.some(k => words.includes(k));
        if (has('is', 'has', 'should', 'can', 'enable')) return 'boolean';
        if (has('count', 'qty', 'quantity', 'number', 'age', 'amount', 'price', 'total', 'rating', 'score', 'percent', 'year', 'days', 'weight', 'height')) return 'number';
        if (has('description', 'desc', 'bio', 'summary', 'details', 'notes', 'content', 'body', 'instructions', 'context', 'background', 'paragraph')) return 'longtext';
        return 'text';
    }

    function _qfFieldControlHtml(v, idx, value) {
        const attrs = 'data-qf-idx="' + idx + '"';
        if (v.type === 'boolean') {
            const opts = ['', 'Yes', 'No'].map(o =>
                '<option value="' + o + '"' + (value === o ? ' selected' : '') + '>' + (o || '\u2014') + '</option>'
            ).join('');
            return '<select class="forge-input qf-var-input" ' + attrs + '>' + opts + '</select>';
        }
        if (v.type === 'number') {
            return '<input type="number" class="forge-input qf-var-input" ' + attrs +
                ' value="' + escapeAttr(value) + '" placeholder="' + escapeAttr(v.token) + '" />';
        }
        const rows = v.type === 'longtext' ? 3 : 1;
        return '<textarea class="forge-input qf-var-input" ' + attrs + ' rows="' + rows + '" placeholder="' +
            escapeAttr(v.token) + '">' + escapeHtml(value) + '</textarea>';
    }

    function _qfTypeSelectHtml(v, idx) {
        const types = ['text', 'longtext', 'number', 'boolean'];
        const labels = { text: 'Text', longtext: 'Long text', number: 'Number', boolean: 'Yes/No' };
        const opts = types.map(t =>
            '<option value="' + t + '"' + (v.type === t ? ' selected' : '') + '>' + labels[t] + '</option>'
        ).join('');
        return '<select class="qf-type-select" data-qf-type-idx="' + idx + '" aria-label="Field type for ' +
            escapeAttr(v.name || v.token) + '">' + opts + '</select>';
    }

    function _qfWireFieldInput(el) {
        const evt = el.tagName === 'SELECT' ? 'change' : 'input';
        el.addEventListener(evt, () => {
            if (el.tagName === 'TEXTAREA') {
                el.style.height = 'auto';
                el.style.height = Math.min(el.scrollHeight, 120) + 'px';
            }
            _qfRenderPreview();
        });
    }

    function _qfRenderForm() {
        const src = $('#qfSource')?.value || '';
        const list = $('#qfVarList');
        if (!list) return;
        const extracted = _qfExtractVars(src);
        _qfVars = extracted.map(v => {
            const remembered = _qfMemGet(v.name);
            return { token: v.token, name: v.name, type: remembered.type || _qfGuessType(v.name), value: remembered.value || '' };
        });
        const countEl = $('#qfVarCount');
        if (countEl) countEl.textContent = _qfVars.length;

        if (!_qfVars.length) {
            list.innerHTML = '<div class="qf-empty">No placeholders found.<br>Use <code>[square brackets]</code> or <code>{{curly pairs}}</code> in the template.</div>';
            _qfRenderPreview();
            return;
        }
        list.innerHTML = _qfVars.map((v, i) => {
            const value = v.value;
            return '<div class="qf-field">' +
                '<div class="qf-field-head">' +
                '<label class="qf-field-label" title="' + escapeAttr(v.token) + '">' + escapeHtml(v.name || v.token) + '</label>' +
                _qfTypeSelectHtml(v, i) +
                '</div>' +
                _qfFieldControlHtml(v, i, value) +
                '</div>';
        }).join('');
        list.querySelectorAll('.qf-var-input').forEach(_qfWireFieldInput);
        list.querySelectorAll('.qf-type-select').forEach(sel => {
            sel.addEventListener('change', () => {
                const idx = Number(sel.dataset.qfTypeIdx);
                const v = _qfVars[idx];
                if (!v) return;
                const wrapper = sel.closest('.qf-field');
                const oldInput = wrapper.querySelector('.qf-var-input');
                const currentValue = oldInput ? oldInput.value : '';
                v.type = sel.value;
                oldInput.outerHTML = _qfFieldControlHtml(v, idx, currentValue);
                const newInput = wrapper.querySelector('.qf-var-input');
                _qfWireFieldInput(newInput);
                _qfRemember({ [v.name]: { value: newInput ? newInput.value : currentValue, type: v.type } });
                _qfRenderPreview();
            });
        });
        _qfRenderPreview();
    }

    function _qfValues() {
        const vals = {};
        $$('#qfVarList .qf-var-input').forEach(ta => {
            const v = _qfVars[Number(ta.dataset.qfIdx)];
            if (v) vals[v.name] = ta.value;
        });
        return vals;
    }

    function _qfResult() {
        let text = $('#qfSource')?.value || '';
        const vals = _qfValues();
        _qfVars.forEach(v => {
            const val = (vals[v.name] || '').trim();
            if (val) text = text.split(v.token).join(val);
        });
        return text;
    }

    function _qfRenderPreview() {
        const out = $('#qfPreview');
        if (!out) return;
        const src = $('#qfSource')?.value || '';
        if (!src.trim()) {
            out.innerHTML = '<span class="hint">Pick a prompt or paste a template on the left…</span>';
            const st = $('#qfFillStat');
            if (st) st.textContent = '';
            return;
        }
        const text = _qfResult();
        let html = escapeHtml(text);
        // Any tokens still present were left unfilled — highlight them.
        let remaining = 0;
        _qfVars.forEach(v => {
            const esc = escapeHtml(v.token);
            if (html.includes(esc)) {
                remaining += 1;
                html = html.split(esc).join('<mark class="qf-missing">' + esc + '</mark>');
            }
        });
        out.innerHTML = html;
        const st = $('#qfFillStat');
        if (st) st.textContent = _qfVars.length ?
            (_qfVars.length - remaining) + ' of ' + _qfVars.length + ' filled' :
            '';
    }

    window.openFillWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#fillWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'fill'));
        _wsFillPromptPicker('#qfPicker');
        setTimeout(() => $('#qfSource')?.focus(), 80);
    };

    function closeFillWorkspace() {
        $('#fillWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function _qfRememberAll() {
        const vals = {};
        $$('#qfVarList .qf-var-input').forEach(el => {
            const v = _qfVars[Number(el.dataset.qfIdx)];
            if (v) vals[v.name] = { value: el.value, type: v.type };
        });
        _qfRemember(vals);
    }

    function initFillWorkspace() {
        const ws = $('#fillWorkspace');
        if (!ws) return;
        $('#closeFillBtn')?.addEventListener('click', closeFillWorkspace);
        $('#qfSource')?.addEventListener('input', _qfRenderForm);
        $('#qfPicker')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#qfPicker');
            if (!p) return;
            const src = $('#qfSource');
            if (src) {
                src.value = p.content || '';
                _qfRenderForm();
            }
        });
        $('#qfCopyBtn')?.addEventListener('click', async () => {
            const text = _qfResult().trim();
            if (!text) {
                toast('Nothing to copy yet', 'warning');
                return;
            }
            _qfRememberAll();
            if (await copyToClipboard(text)) toast('Filled prompt copied', 'success');
        });
        $('#qfSaveBtn')?.addEventListener('click', async () => {
            const text = _qfResult().trim();
            if (!text) {
                toast('Fill the template first', 'warning');
                return;
            }
            _qfRememberAll();
            const picked = _wsPickedPrompt('#qfPicker');
            const title = ((picked?.title || text.split(' ').slice(0, 6).join(' ')) + ' (filled)').slice(0, 120);
            try {
                const cats = Array.isArray(picked?.categories) ? picked.categories.join(', ') : (picked?.categories || '');
                const result = await api('/prompts', {
                    method: 'POST',
                    body: {
                        title,
                        content: text,
                        description: 'Filled via Quick Fill workspace',
                        categories: cats,
                        tags: 'quick-fill'
                    }
                });
                await loadPrompts();
                await loadFilterOptions();
                toast('Saved: ' + title, 'success');
                closeFillWorkspace();
                if (result?.id) setTimeout(() => openDetail(result.id), 200);
            } catch {
                toast('Could not save', 'error');
            }
        });
        $('#qfClearBtn')?.addEventListener('click', () => {
            const src = $('#qfSource');
            if (src) src.value = '';
            const pk = $('#qfPicker');
            if (pk) pk.selectedIndex = 0;
            _qfRenderForm();
        });
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeFillWorkspace();
        });
    }

    /* ============================================================================
       PROMPT AUDITOR WORKSPACE
       Offline rubric scoring across six dimensions plus a findings list.
       Optional AI deep critique through the shared callAI() helper.
       data-view="audit" | openAuditWorkspace() | initAuditWorkspace()
       ============================================================================ */

    const AUD_VAGUE = ['some', 'various', 'stuff', 'things', 'good', 'nice', 'interesting', 'a few', 'better', 'appropriate', 'relevant', 'etc'];

    let _audLastResult = null;

    function _audScore(text) {
        const t = (text || '').trim();
        const lower = t.toLowerCase();
        const words = (t.match(/\S+/g) || []).length;
        const dims = {};
        const findings = [];

        // Role & persona
        const hasRole = /\b(you are|act as|act like|adopt|persona of|role of|behave as)\b/i.test(t);
        dims['Role & persona'] = hasRole ? 95 : 25;
        if (!hasRole) findings.push({
            sev: 'low',
            text: 'No role or persona set. Opening with "You are a…" anchors expertise and voice.'
        });

        // Task clarity
        const verbRx = /\b(write|create|generate|analy[sz]e|summari[sz]e|list|explain|rewrite|classify|extract|translate|design|draft|produce|evaluate|compare|review|identify|describe|outline|build|compose)\b/i;
        const hasVerb = verbRx.test(t);
        const hasQuant = /\b\d+\b|\b(one|two|three|four|five|ten)\b/i.test(t);
        dims['Task clarity'] = (hasVerb ? 55 : 15) + (hasQuant ? 25 : 5) + (words >= 8 ? 15 : 0);
        if (!hasVerb) findings.push({
            sev: 'high',
            text: 'No clear action verb found. State exactly what the AI should do (write, analyse, list…).'
        });
        if (words < 8) findings.push({
            sev: 'med',
            text: 'Very short prompt (' + words + ' words). Underspecified prompts produce generic output.'
        });

        // Context
        const hasCtx = /\b(context|background|given|about|audience|scenario|we are|the user|for a|aimed at)\b/i.test(t) || words > 60;
        dims['Context'] = hasCtx ? 80 : 30;
        if (!hasCtx) findings.push({
            sev: 'med',
            text: 'No background or audience context. Say who it is for and what situation it serves.'
        });

        // Constraints
        const hasCons = /\b(don'?t|do not|never|avoid|must|no more than|at most|at least|limit|only|exclude|without)\b/i.test(t);
        dims['Constraints'] = hasCons ? 85 : 35;
        if (!hasCons) findings.push({
            sev: 'low',
            text: 'No constraints. Boundaries ("no jargon", "max 200 words") sharpen results.'
        });

        // Output format
        const hasFmt = /\b(format|bullet|numbered|table|json|xml|markdown|heading|word count|words|paragraphs?|tone|respond in|structure)\b/i.test(t);
        dims['Output format'] = hasFmt ? 90 : 30;
        if (!hasFmt) findings.push({
            sev: 'med',
            text: 'No output format specified. Say how the answer should be structured.'
        });

        // Examples
        const hasEx = /\b(example|e\.g\.|for instance|for example|such as|input:|output:)\b/i.test(t);
        dims['Examples'] = hasEx ? 90 : 45;

        // Extra findings beyond the rubric
        const vagueHits = AUD_VAGUE.filter(w => new RegExp('\\b' + w.replace('.', '\\.') + '\\b', 'i').test(lower));
        if (vagueHits.length >= 2) findings.push({
            sev: 'med',
            text: 'Vague wording: ' + vagueHits.slice(0, 5).map(w => '“' + w + '”').join(', ') + '. Swap for concrete terms.'
        });
        const placeholders = _qfExtractVars(t);
        if (placeholders.length) findings.push({
            sev: 'high',
            text: placeholders.length + ' unfilled placeholder' + (placeholders.length > 1 ? 's' : '') + ' (' + placeholders.slice(0, 3).map(p => p.token).join(', ') + '…). Fill them in Quick Fill before running.'
        });
        if (words > 120 && !t.includes('\n')) findings.push({
            sev: 'med',
            text: 'Wall of text — ' + words + ' words with no line breaks. Split into sections or bullets.'
        });
        if (/\b(concise|brief|short)\b/i.test(t) && /\b(detailed|comprehensive|in-depth|thorough)\b/i.test(t)) {
            findings.push({
                sev: 'high',
                text: 'Conflicting instructions: asks for both concise and detailed output. Pick one or scope each.'
            });
        }
        if (/ignore (all |any )?(previous|prior|above) instructions/i.test(t)) {
            findings.push({
                sev: 'high',
                text: 'Contains "ignore previous instructions" — commonly flagged or misinterpreted by models.'
            });
        }

        const vals = Object.values(dims);
        const overall = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
        return {
            overall,
            dims,
            findings,
            words,
            tokens: _wsEstTokens(t)
        };
    }

    function _audRender(result) {
        const scoreEl = $('#audScoreNum');
        if (scoreEl) scoreEl.textContent = result.overall;
        const badge = $('#audScoreBadge');
        if (badge) {
            badge.textContent = result.overall >= 80 ? 'Strong' : result.overall >= 55 ? 'Decent' : 'Needs work';
            badge.className = 'aud-badge ' + (result.overall >= 80 ? 'aud-good' : result.overall >= 55 ? 'aud-mid' : 'aud-bad');
        }
        const meta = $('#audMeta');
        if (meta) meta.textContent = result.words + ' words · ~' + result.tokens + ' tokens';

        const dimsEl = $('#audDims');
        if (dimsEl) dimsEl.innerHTML = Object.entries(result.dims).map(([label, v]) =>
            '<div class="aud-dim">' +
            '<div class="aud-dim-head"><span>' + escapeHtml(label) + '</span><span class="aud-dim-val">' + v + '</span></div>' +
            '<div class="aud-bar"><div class="aud-bar-fill' + (v >= 70 ? '' : v >= 45 ? ' mid' : ' low') + '" style="width:' + v + '%"></div></div>' +
            '</div>').join('');

        const list = $('#audFindings');
        if (list) {
            list.innerHTML = result.findings.length ?
                result.findings.map(f =>
                    '<div class="aud-finding aud-sev-' + f.sev + '">' +
                    '<span class="aud-sev-chip">' + (f.sev === 'high' ? 'High' : f.sev === 'med' ? 'Med' : 'Low') + '</span>' +
                    '<span>' + escapeHtml(f.text) + '</span>' +
                    '</div>').join('') :
                '<div class="hint" style="padding:var(--sp-3);">No issues found — this prompt covers the fundamentals. ✓</div>';
        }
        const results = $('#audResults');
        if (results) results.style.display = '';
    }

    window.openAuditWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#auditWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'audit'));
        _wsFillPromptPicker('#audPicker');
        setTimeout(() => $('#audInput')?.focus(), 80);
    };

    function closeAuditWorkspace() {
        $('#auditWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initAuditWorkspace() {
        const ws = $('#auditWorkspace');
        if (!ws) return;
        $('#closeAuditBtn')?.addEventListener('click', closeAuditWorkspace);
        $('#audPicker')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#audPicker');
            if (p) {
                const el = $('#audInput');
                if (el) el.value = p.content || '';
            }
        });
        $('#audRunBtn')?.addEventListener('click', () => {
            const text = $('#audInput')?.value?.trim();
            if (!text) {
                toast('Paste a prompt first', 'warning');
                return;
            }
            _audLastResult = _audScore(text);
            _audRender(_audLastResult);
        });

        $('#audSaveBtn')?.addEventListener('click', async () => {
            const text = $('#audInput')?.value?.trim();
            if (!text) {
                toast('Audit a prompt first', 'warning');
                return;
            }
            const freshResult = _audScore(text);
            const picked = _wsPickedPrompt('#audPicker');
            const title = ((picked?.title || 'Audited prompt') + ' (audited)').slice(0, 120);
            const topFindings = freshResult.findings.slice(0, 3).map(f => f.text).join(' | ');
            const note = 'Audited via Prompt Auditor workspace — score ' + freshResult.overall + '/100.' +
                (topFindings ? ' Top findings: ' + topFindings : '');
            const saved = await _wsSaveOrReplace({
                text,
                sourcePrompt: picked,
                newTitle: title,
                description: 'Audited via Prompt Auditor workspace',
                tags: 'audited',
                extraNote: note,
            });
            if (saved?.id) {
                closeAuditWorkspace();
                setTimeout(() => openDetail(saved.id), 200);
            }
        });
        $('#audAiBtn')?.addEventListener('click', async function() {
            const text = $('#audInput')?.value?.trim();
            if (!text) {
                toast('Paste a prompt first', 'warning');
                return;
            }
            const out = $('#audAiOutput');
            this.disabled = true;
            if (out) {
                out.style.display = '';
                out.innerHTML = '<span class="hint">⏳ Running deep critique…</span>';
            }
            try {
                const sys = 'You are a prompt engineering reviewer. Critique the given prompt: name its three biggest weaknesses, then rewrite the weakest sentence. Be specific and terse. Plain text, no markdown headings.';
                const result = await callAI(sys, text, 800);
                if (out) out.textContent = result;
            } catch (err) {
                if (out) out.innerHTML = '<span class="hint">Error: ' + escapeHtml(err.message) + '</span>';
                toast('Critique failed: ' + err.message, 'error');
            } finally {
                this.disabled = false;
            }
        });
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeAuditWorkspace();
        });
    }

    /* ============================================================================
       DIFF LENS WORKSPACE
       Word-level diff between two prompts with similarity score. Offline. Free.
       data-view="diff" | openDiffWorkspace() | initDiffWorkspace()
       ============================================================================ */

    // Token-level LCS diff. Returns array of {op: 'eq'|'del'|'ins', text}.
    function _diffTokens(a, b) {
        const at = a.match(/\S+|\s+/g) || [];
        const bt = b.match(/\S+|\s+/g) || [];
        const CAP = 3000;
        if (at.length > CAP || bt.length > CAP) return null; // too large for O(n·m)
        const n = at.length,
            m = bt.length;
        // LCS table (single-int rows to keep memory sane)
        const dp = Array.from({
            length: n + 1
        }, () => new Uint16Array(m + 1));
        for (let i = n - 1; i >= 0; i--) {
            for (let j = m - 1; j >= 0; j--) {
                dp[i][j] = at[i] === bt[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
            }
        }
        const ops = [];
        let i = 0,
            j = 0;
        while (i < n && j < m) {
            if (at[i] === bt[j]) {
                ops.push({
                    op: 'eq',
                    text: at[i]
                });
                i++;
                j++;
            } else if (dp[i + 1][j] >= dp[i][j + 1]) {
                ops.push({
                    op: 'del',
                    text: at[i]
                });
                i++;
            } else {
                ops.push({
                    op: 'ins',
                    text: bt[j]
                });
                j++;
            }
        }
        while (i < n) {
            ops.push({
                op: 'del',
                text: at[i++]
            });
        }
        while (j < m) {
            ops.push({
                op: 'ins',
                text: bt[j++]
            });
        }
        return ops;
    }

    function _diffRun() {
        const a = $('#diffInputA')?.value || '';
        const b = $('#diffInputB')?.value || '';
        const out = $('#diffOutput');
        if (!out) return;
        if (!a.trim() || !b.trim()) {
            toast('Fill both sides first', 'warning');
            return;
        }
        const ops = _diffTokens(a, b);
        if (!ops) {
            out.innerHTML = '<span class="hint">Texts too large for word-level diff (3,000 token cap per side).</span>';
            return;
        }

        let html = '',
            eqCount = 0,
            wordTotal = 0;
        ops.forEach(o => {
            const esc = escapeHtml(o.text);
            if (o.op === 'eq') {
                html += esc;
                if (/\S/.test(o.text)) eqCount++;
            } else if (o.op === 'del') html += '<del class="dif-del">' + esc + '</del>';
            else html += '<ins class="dif-ins">' + esc + '</ins>';
            if (/\S/.test(o.text)) wordTotal++;
        });
        out.innerHTML = html;

        const aw = (a.match(/\S+/g) || []).length,
            bw = (b.match(/\S+/g) || []).length;
        const sim = (aw + bw) ? Math.round((2 * eqCount / (aw + bw)) * 100) : 0;
        const stat = $('#diffStats');
        if (stat) stat.innerHTML =
            '<span class="dif-sim">' + sim + '% similar</span>' +
            '<span>A: ' + aw + ' words · ~' + _wsEstTokens(a) + ' tok</span>' +
            '<span>B: ' + bw + ' words · ~' + _wsEstTokens(b) + ' tok</span>';
    }

    window.openDiffWorkspace = function() {
        const ws = $('#diffWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'diff'));
        _wsFillPromptPicker('#diffPickerA');
        _wsFillPromptPicker('#diffPickerB');
        setTimeout(() => $('#diffInputA')?.focus(), 80);
    };

    function closeDiffWorkspace() {
        $('#diffWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initDiffWorkspace() {
        const ws = $('#diffWorkspace');
        if (!ws) return;
        $('#closeDiffBtn')?.addEventListener('click', closeDiffWorkspace);
        $('#diffPickerA')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#diffPickerA');
            if (p) {
                const el = $('#diffInputA');
                if (el) el.value = p.content || '';
            }
        });
        $('#diffPickerB')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#diffPickerB');
            if (p) {
                const el = $('#diffInputB');
                if (el) el.value = p.content || '';
            }
        });
        $('#diffRunBtn')?.addEventListener('click', _diffRun);
        $('#diffSwapBtn')?.addEventListener('click', () => {
            const a = $('#diffInputA'),
                b = $('#diffInputB');
            if (!a || !b) return;
            const tmp = a.value;
            a.value = b.value;
            b.value = tmp;
            if ($('#diffOutput')?.textContent?.trim()) _diffRun();
        });
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeDiffWorkspace();
        });
    }

    /* ============================================================================
       COST LENS WORKSPACE
       Token + cost estimate across common models. Static price table — offline.
       Prices are indicative (checked mid-2026); always verify with the provider.
       data-view="cost" | openCostWorkspace() | initCostWorkspace()
       ============================================================================ */

    const COST_MODELS = [{
            name: 'Claude Opus',
            ctx: 200000,
            inPM: 15.00,
            outPM: 75.00
        },
        {
            name: 'Claude Sonnet',
            ctx: 200000,
            inPM: 3.00,
            outPM: 15.00
        },
        {
            name: 'Claude Haiku',
            ctx: 200000,
            inPM: 1.00,
            outPM: 5.00
        },
        {
            name: 'GPT-4o',
            ctx: 128000,
            inPM: 2.50,
            outPM: 10.00
        },
        {
            name: 'GPT-4o mini',
            ctx: 128000,
            inPM: 0.15,
            outPM: 0.60
        },
        {
            name: 'Gemini Pro',
            ctx: 2000000,
            inPM: 1.25,
            outPM: 5.00
        },
        {
            name: 'Gemini Flash',
            ctx: 1000000,
            inPM: 0.10,
            outPM: 0.40
        },
    ];

    function _costFmt(n) {
        if (n >= 1) return '$' + n.toFixed(2);
        if (n >= 0.01) return '$' + n.toFixed(3);
        return '$' + n.toFixed(5);
    }

    function _costRun() {
        const text = $('#costInput')?.value || '';
        const outTok = Math.max(0, parseInt($('#costOutTokens')?.value, 10) || 500);
        const perDay = Math.max(1, parseInt($('#costRunsDay')?.value, 10) || 1);
        const inTok = _wsEstTokens(text);
        const meta = $('#costMeta');
        if (meta) meta.textContent = '~' + inTok.toLocaleString() + ' input tokens · ' + (text.match(/\S+/g) || []).length + ' words';

        const body = $('#costTableBody');
        if (!body) return;
        body.innerHTML = COST_MODELS.map(mdl => {
            const run = (inTok / 1e6) * mdl.inPM + (outTok / 1e6) * mdl.outPM;
            const month = run * perDay * 30;
            const fit = Math.min(100, Math.round(((inTok + outTok) / mdl.ctx) * 100));
            return '<tr>' +
                '<td>' + escapeHtml(mdl.name) + '</td>' +
                '<td class="cl-num">' + _costFmt(run) + '</td>' +
                '<td class="cl-num">' + _costFmt(run * perDay) + '</td>' +
                '<td class="cl-num">' + _costFmt(month) + '</td>' +
                '<td><div class="cl-fit"><div class="cl-fit-fill' + (fit > 85 ? ' cl-fit-hot' : '') + '" style="width:' + Math.max(fit, 2) + '%"></div></div>' +
                '<span class="cl-fit-label">' + fit + '%</span></td>' +
                '</tr>';
        }).join('');
        const results = $('#costResults');
        if (results) results.style.display = '';
    }

    window.openCostWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#costWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'cost'));
        _wsFillPromptPicker('#costPicker');
        setTimeout(() => $('#costInput')?.focus(), 80);
    };

    function closeCostWorkspace() {
        $('#costWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initCostWorkspace() {
        const ws = $('#costWorkspace');
        if (!ws) return;
        $('#closeCostBtn')?.addEventListener('click', closeCostWorkspace);
        $('#costPicker')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#costPicker');
            if (p) {
                const el = $('#costInput');
                if (el) el.value = p.content || '';
                _costRun();
            }
        });
        ['#costInput', '#costOutTokens', '#costRunsDay'].forEach(sel => {
            $(sel)?.addEventListener('input', () => {
                if ($('#costResults')?.style.display !== 'none') _costRun();
            });
        });
        $('#costRunBtn')?.addEventListener('click', _costRun);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeCostWorkspace();
        });
    }

    /* ============================================================================
       PROMPT FORKING WORKSTATION
       Two-pane workspace: original/parent on the left (read-only), fork on the
       right (editable). Reuses existing fork/lineage API routes.
       ============================================================================ */

    let _fwState = { currentId: null, sourceId: null };

    async function _fwLoadLineage(promptId) {
        const res = await fetch('/api/prompts/' + promptId + '/lineage');
        if (!res.ok) return [];
        const data = await res.json();
        return data.chain || [];
    }

    function _fwRenderBreadcrumb(chain, currentPrompt) {
        const el = $('#forkBreadcrumb');
        if (!el) return;
        const all = chain.concat([currentPrompt]);
        const parts = all.map(function(p, i) {
            const isLast = i === all.length - 1;
            const label = escapeHtml(p.title || 'Untitled');
            return isLast
                ? '<span class="fw-crumb" style="cursor:default;color:var(--ink-1);font-weight:600;">' + label + '</span>'
                : '<span class="fw-crumb" data-fork-jump="' + p.id + '">' + label + '</span>';
        });
        el.innerHTML = parts.join('<span class="fw-crumb-sep">/</span>');
        el.querySelectorAll('[data-fork-jump]').forEach(function(node) {
            node.addEventListener('click', function() {
                window.openForkWorkstation(parseInt(node.dataset.forkJump, 10));
            });
        });
    }

    function _fwRenderOriginalPane(sourcePrompt, isDeleted) {
        const badge = $('#forkOriginalBadge');
        const titleEl = $('#forkOriginalTitle');
        const contentEl = $('#forkOriginalContent');
        if (!sourcePrompt) {
            if (badge) { badge.textContent = 'Original deleted'; badge.className = 'fw-badge fw-badge-deleted'; }
            if (titleEl) titleEl.textContent = '(deleted)';
            if (contentEl) contentEl.textContent = '';
            return;
        }
        if (isDeleted) {
            if (badge) { badge.textContent = 'Original deleted'; badge.className = 'fw-badge fw-badge-deleted'; }
            if (titleEl) titleEl.textContent = sourcePrompt.title || 'Untitled';
            if (contentEl) contentEl.textContent = sourcePrompt.content || '';
            return;
        }
        if (badge) {
            const isFork = !!sourcePrompt.parent_id;
            badge.textContent = isFork ? 'Parent Fork' : 'Original';
            badge.className = 'fw-badge ' + (isFork ? 'fw-badge-fork' : 'fw-badge-original');
        }
        if (titleEl) titleEl.textContent = sourcePrompt.title || 'Untitled';
        if (contentEl) contentEl.textContent = sourcePrompt.content || '';
    }

    window.openForkWorkstation = async function(promptId) {
        if (!state.isPremium) { showPremiumModal(); return; }
        const ws = $('#forkWorkstation');
        if (!ws || !promptId) return;
        const prompt = state.prompts.find(function(p) { return p.id === promptId; });
        if (!prompt) return;

        _fwState.currentId = promptId;
        _fwState.sourceId = prompt.parent_id || null;

        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(function(el) { el.classList.toggle('active', el.dataset.view === 'fork'); });

        const chain = await _fwLoadLineage(promptId);
        _fwRenderBreadcrumb(chain, prompt);

        let sourcePrompt = null;
        let sourceDeleted = false;
        if (prompt.parent_id) {
            sourcePrompt = state.prompts.find(function(p) { return p.id === prompt.parent_id; }) || null;
            if (!sourcePrompt) {
                sourceDeleted = true;
                if (prompt.fork_snapshot) {
                    try { sourcePrompt = JSON.parse(prompt.fork_snapshot); } catch (e) { sourcePrompt = null; }
                }
            }
        }
        _fwRenderOriginalPane(sourcePrompt || (prompt.parent_id ? null : prompt), sourceDeleted);

        const titleInput = $('#forkTitleInput');
        const contentInput = $('#forkContentInput');
        if (titleInput) titleInput.value = prompt.title || '';
        if (contentInput) contentInput.value = prompt.content || '';
        const statusEl = $('#forkSaveStatus');
        if (statusEl) statusEl.textContent = '';
    };

    function closeForkWorkstation() {
        $('#forkWorkstation')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(function(el) { el.classList.toggle('active', el.dataset.view === 'library'); });
    }

    async function _fwCreateNewFork() {
        if (!_fwState.currentId) return;
        const res = await fetch('/api/prompts/' + _fwState.currentId + '/fork', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({})
        });
        if (!res.ok) return;
        const data = await res.json();
        await loadPrompts();
        window.openForkWorkstation(data.id);
    }

    async function _fwSaveCurrent() {
        if (!_fwState.currentId) return;
        const statusEl = $('#forkSaveStatus');
        const title = $('#forkTitleInput')?.value ?? '';
        const content = $('#forkContentInput')?.value ?? '';
        if (statusEl) statusEl.textContent = 'Saving…';
        const res = await fetch('/api/prompts/' + _fwState.currentId, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: title, content: content })
        });
        if (!res.ok) {
            if (statusEl) statusEl.textContent = 'Save failed';
            return;
        }
        await loadPrompts();
        if (statusEl) statusEl.textContent = 'Saved';
    }

    function initForkWorkstation() {
        const ws = $('#forkWorkstation');
        if (!ws) return;
        $('#closeForkBtn')?.addEventListener('click', closeForkWorkstation);
        $('#newForkBtn')?.addEventListener('click', _fwCreateNewFork);
        $('#forkSaveBtn')?.addEventListener('click', _fwSaveCurrent);
        $('#forkFullEditorBtn')?.addEventListener('click', function() {
            const idToEdit = _fwState.currentId;
            closeForkWorkstation();
            window.PL_openViewer(idToEdit);
        });
        ws.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') closeForkWorkstation();
        });
    }

    /* ============================================================================
       PROMPT FORKING WORKSPACE V2
       First-class prompt branches, evaluation, lineage and experimentation.
       ============================================================================ */
    const _pfw = { rootId:null, activeId:null, compareId:null, nodes:new Map(), tests:[], results:{}, winnerId:null };
    const _pfwKey = rootId => 'promptlib.pfw.v2.' + rootId;
    function _pfwSaveLocal(){if(!_pfw.rootId)return;try{localStorage.setItem(_pfwKey(_pfw.rootId),JSON.stringify({tests:_pfw.tests,results:_pfw.results,winnerId:_pfw.winnerId}));}catch(e){}}
    function _pfwLoadLocal(rootId){try{const d=JSON.parse(localStorage.getItem(_pfwKey(rootId))||'{}');_pfw.tests=Array.isArray(d.tests)?d.tests:[];_pfw.results=d.results&&typeof d.results==='object'?d.results:{};_pfw.winnerId=d.winnerId||null;}catch(e){_pfw.tests=[];_pfw.results={};_pfw.winnerId=null;}if(!_pfw.tests.length)_pfw.tests=[{id:'default-1',name:'Core task',input:'Use this test case to judge whether the prompt reliably produces the intended result.',expected:'The response should follow the prompt precisely, remain useful, and avoid inventing requirements.'}];_pfwSaveLocal();}
    async function _pfwGetPrompt(id){const local=state.prompts.find(p=>Number(p.id)===Number(id));if(local)return local;const r=await fetch('/api/prompts/'+id);return r.ok?await r.json():null;}
    async function _pfwLoadTree(rootId){_pfw.nodes.clear();const root=await _pfwGetPrompt(rootId);if(!root)return;const walk=async p=>{_pfw.nodes.set(Number(p.id),p);const r=await fetch('/api/prompts/'+p.id+'/forks');if(!r.ok)return;const d=await r.json();for(const child of(d.forks||[]))await walk(child);};await walk(root);}
    function _pfwChildren(id){return[..._pfw.nodes.values()].filter(p=>Number(p.parent_id)===Number(id));}
    function _pfwRenderTree(){const el=$('#pfwTree');if(!el)return;const root=_pfw.nodes.get(Number(_pfw.rootId));if(!root){el.innerHTML='<div class="pfw-empty">Select a prompt to begin an experiment.</div>';return;}const render=(p,depth)=>{const children=_pfwChildren(p.id),r=_pfw.results[p.id],score=r&&r.score!=null?r.score:null,winner=Number(_pfw.winnerId)===Number(p.id),active=Number(_pfw.activeId)===Number(p.id);let html='<div class="pfw-tree-node '+(active?'is-active ':'')+(winner?'is-winner ':'')+'" style="--pfw-depth:'+depth+'" data-pfw-node="'+p.id+'"><button class="pfw-node-main" type="button"><span class="pfw-node-dot"></span><span class="pfw-node-title">'+escapeHtml(p.title||'Untitled')+'</span><span class="pfw-node-kind '+(p.parent_id?'':'root')+'">'+(p.parent_id?'fork':'root')+'</span>'+(score==null?'':'<span class="pfw-node-score">'+score+'</span>')+(winner?'<span class="material-symbols-outlined pfw-winner-icon">star</span>':'')+'</button></div>';if(children.length)html+='<div class="pfw-tree-children">'+children.map(c=>render(c,depth+1)).join('')+'</div>';return html;};el.innerHTML=render(root,0);const tc=$('#pfwTreeCount'),bc=$('#pfwBranchCount'),wl=$('#pfwWinnerLabel');if(tc)tc.textContent=_pfw.nodes.size+' versions';if(bc)bc.textContent=_pfw.nodes.size;if(wl)wl.textContent=_pfw.winnerId&&_pfw.nodes.get(Number(_pfw.winnerId))?(_pfw.nodes.get(Number(_pfw.winnerId)).title||'Marked'):'None';el.querySelectorAll('[data-pfw-node]').forEach(n=>n.querySelector('.pfw-node-main').addEventListener('click',()=>_pfwSelect(Number(n.dataset.pfwNode))));}
    function _pfwSetMode(mode){const ws=$('#promptForkingWorkspace');if(!ws)return;ws.querySelectorAll('[data-pfw-mode]').forEach(b=>b.classList.toggle('active',b.dataset.pfwMode===mode));ws.querySelectorAll('[data-pfw-panel]').forEach(p=>p.hidden=p.dataset.pfwPanel!==mode);if(mode==='compare')_pfwRenderCompare();if(mode==='tests')_pfwRenderTests();if(mode==='history')_pfwRenderHistory();}
    function _pfwRenderActive(){const p=_pfw.nodes.get(Number(_pfw.activeId));if(!p)return;const t=$('#pfwTitleInput'),c=$('#pfwContentInput'),par=$('#pfwParentLabel'),badge=$('#pfwStatusBadge'),score=$('#pfwActiveScore');if(t)t.value=p.title||'';if(c)c.value=p.content||'';if(par){const pp=p.parent_id?_pfw.nodes.get(Number(p.parent_id)):null;par.textContent=pp?'Forked from '+(pp.title||'Untitled'):'Original prompt';}if(badge){badge.textContent=_pfw.winnerId==p.id?'Winner':p.status==='deprecated'?'Archived':p.parent_id?'Branch':'Root';badge.className='pfw-status-badge '+(_pfw.winnerId==p.id?'winner':p.status==='deprecated'?'archived':'');}if(score){const r=_pfw.results[p.id];score.textContent=r&&r.score!=null?r.score+'/100':'Not evaluated';}_pfwRenderDiff();}
    function _pfwDiff(a,b){const aa=(a||'').split(/\r?\n/),bb=(b||'').split(/\r?\n/),out=[];let i=0,j=0;while(i<aa.length||j<bb.length){if(i<aa.length&&j<bb.length&&aa[i]===bb[j]){out.push({type:'same',text:aa[i++]});j++;}else if(i<aa.length&&(j>=bb.length||!bb.slice(j,Math.min(bb.length,j+4)).includes(aa[i])))out.push({type:'del',text:aa[i++]});else if(j<bb.length)out.push({type:'add',text:bb[j++]});}return out;}
    function _pfwRenderDiff(){const el=$('#pfwMiniDiff'),p=_pfw.nodes.get(Number(_pfw.activeId));if(!el||!p)return;const parent=p.parent_id?_pfw.nodes.get(Number(p.parent_id)):null;if(!parent){el.innerHTML='<div class="pfw-diff-empty">This is the root. Create a fork to see changes.</div>';return;}el.innerHTML=_pfwDiff(parent.content,p.content).slice(0,180).map(x=>'<div class="pfw-diff-line '+x.type+'"><span>'+(x.type==='add'?'+':x.type==='del'?'−':' ')+'</span><code>'+escapeHtml(x.text||' ')+'</code></div>').join('');}
    function _pfwRenderCompare(){const a=_pfw.nodes.get(Number(_pfw.activeId)),sel=$('#pfwCompareSelect'),l=$('#pfwCompareLeft'),r=$('#pfwCompareRight'),m=$('#pfwCompareMeta');if(sel){const others=[..._pfw.nodes.values()].filter(p=>Number(p.id)!==Number(_pfw.activeId));sel.innerHTML=others.map(p=>'<option value="'+p.id+'" '+(Number(p.id)===Number(_pfw.compareId)?'selected':'')+'>'+escapeHtml(p.title||'Untitled')+'</option>').join('');if(!_pfw.compareId&&others[0]){_pfw.compareId=Number(others[0].id);sel.value=String(_pfw.compareId);}}const b=_pfw.nodes.get(Number(_pfw.compareId));if(!l||!r)return;if(!b||!a){l.textContent=a?a.content:'';r.textContent='Create another branch to compare.';if(m)m.textContent='';return;}l.textContent=a.content||'';r.textContent=b.content||'';const ar=_pfw.results[a.id],br=_pfw.results[b.id];if(m)m.textContent='A '+(ar?.score??'not run')+' / 100  ·  B '+(br?.score??'not run')+' / 100';if(sel&&!sel.dataset.bound){sel.dataset.bound='1';sel.addEventListener('change',()=>{_pfw.compareId=Number(sel.value);_pfwRenderCompare();});}}
    function _pfwRenderTests(){const list=$('#pfwTestsList');if(!list)return;list.innerHTML=_pfw.tests.map(t=>{const r=_pfw.results[_pfw.activeId+':'+t.id];return'<article class="pfw-test-card"><div class="pfw-test-head"><strong>'+escapeHtml(t.name)+'</strong><button class="pfw-icon-button" data-pfw-test-delete="'+t.id+'" aria-label="Delete test"><span class="material-symbols-outlined">delete</span></button></div><p><b>Input</b><br>'+escapeHtml(t.input)+'</p><p><b>Quality bar</b><br>'+escapeHtml(t.expected)+'</p><div class="pfw-test-result">'+(r?'<span class="pfw-result-score">'+r.score+'/100</span><span>'+escapeHtml(r.summary||'')+'</span>':'<span class="pfw-muted">Not run yet</span>')+'</div></article>';}).join('');list.querySelectorAll('[data-pfw-test-delete]').forEach(b=>b.addEventListener('click',()=>{_pfw.tests=_pfw.tests.filter(t=>t.id!==b.dataset.pfwTestDelete);_pfwSaveLocal();_pfwRenderTests();}));}
    function _pfwRenderHistory(){const el=$('#pfwHistoryList'),p=_pfw.nodes.get(Number(_pfw.activeId));if(!el||!p)return;fetch('/api/prompts/'+p.id+'/versions').then(r=>r.json()).then(vs=>{el.innerHTML=(vs||[]).map(v=>'<button class="pfw-history-row" data-pfw-version="'+v.id+'"><span>'+escapeHtml(v.title||'Untitled')+'</span><time>'+escapeHtml(v.saved_at||'')+'</time></button>').join('')||'<div class="pfw-empty">No saved revisions yet.</div>';el.querySelectorAll('[data-pfw-version]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Restore this revision?'))return;const r=await fetch('/api/prompts/'+p.id+'/versions/'+b.dataset.pfwVersion+'/restore',{method:'POST'});if(r.ok){await loadPrompts();await _pfwLoadTree(_pfw.rootId);await _pfwSelect(p.id);toast('Revision restored','success');}}));}).catch(()=>{el.innerHTML='<div class="pfw-empty">Could not load revision history.</div>';});}
    async function _pfwSelect(id){if(!_pfw.nodes.has(Number(id)))return;_pfw.activeId=Number(id);_pfwRenderTree();_pfwRenderActive();_pfwRenderCompare();_pfwRenderTests();_pfwSetMode('edit');}
    async function _pfwCreateFork(){if(!_pfw.activeId)return;const p=_pfw.nodes.get(Number(_pfw.activeId));const r=await fetch('/api/prompts/'+p.id+'/fork',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:(p.title||'Prompt')+' · Fork'})});if(!r.ok){toast('Could not create fork','error');return;}const d=await r.json();await loadPrompts();await _pfwLoadTree(_pfw.rootId);await _pfwSelect(d.id);toast('New branch created','success');}
    async function _pfwSave(){if(!_pfw.activeId)return;const p=_pfw.nodes.get(Number(_pfw.activeId)),title=$('#pfwTitleInput')?.value.trim(),content=$('#pfwContentInput')?.value||'';if(!title||!content.trim()){toast('A branch needs a title and prompt content','warning');return;}const payload={title,content,description:p.description||'',categories:p.categories||[],tags:p.tags||[],folder_id:p.folder_id||null,colour_label:p.colour_label||'',rating:p.rating||0,notes:p.notes||'',chain_ids:p.chain_ids||[],variable_meta:p.variable_meta||{},chat_turns:p.chat_turns||[],role_id:p.role_id||null,status:p.status||'draft',parent_id:p.parent_id||null,prompt_domain:p.prompt_domain||'',prompt_use_case:p.prompt_use_case||'',prompt_output_format:p.prompt_output_format||'',prompt_tone:p.prompt_tone||''};const r=await fetch('/api/prompts/'+p.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){toast('Save failed','error');return;}await loadPrompts();await _pfwLoadTree(_pfw.rootId);await _pfwSelect(p.id);toast('Branch saved','success');}
    async function _pfwDelete(){const p=_pfw.nodes.get(Number(_pfw.activeId));if(!p||!confirm('Delete this branch? Its children remain independent prompts.'))return;const parent=p.parent_id;const r=await fetch('/api/prompts/'+p.id,{method:'DELETE'});if(!r.ok){toast('Could not delete branch','error');return;}await loadPrompts();await _pfwLoadTree(_pfw.rootId);if(_pfw.nodes.has(Number(parent)))await _pfwSelect(parent);else await _pfwSelect(_pfw.rootId);toast('Branch deleted','success');}
    async function _pfwArchive(){const p=_pfw.nodes.get(Number(_pfw.activeId));if(!p)return;const next=p.status==='deprecated'?'draft':'deprecated';const r=await fetch('/api/prompts/'+p.id+'/status',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:next})});if(!r.ok){toast('Could not change branch status','error');return;}await loadPrompts();await _pfwLoadTree(_pfw.rootId);await _pfwSelect(p.id);}
    function _pfwMarkWinner(){_pfw.winnerId=Number(_pfw.activeId);_pfwSaveLocal();_pfwRenderTree();_pfwRenderActive();toast('Winner marked','success');}
    async function _pfwRunTest(){const p=_pfw.nodes.get(Number(_pfw.activeId)),t=_pfw.tests[0];if(!p||!t||typeof callAI!=='function'){toast('Add a test and configure AI first','warning');return;}try{const output=await callAI(p.content,t.input,1400);const judge='You are a rigorous prompt evaluator. Return strict JSON with score and summary. Score 0-100 for instruction following, usefulness, consistency, specificity and likely task success. Judge the OUTPUT, not the prompt itself.';const judgeInput='PROMPT:\n'+p.content+'\n\nTEST INPUT:\n'+t.input+'\n\nQUALITY BAR:\n'+t.expected+'\n\nOUTPUT:\n'+output;const raw=await callAI(judge,judgeInput,900),parsed=JSON.parse(String(raw).replace(/^\`\`\`json\s*/i,'').replace(/\`\`\`$/,'').trim()),score=Math.max(0,Math.min(100,Number(parsed.score)||0));_pfw.results[p.id]={score,summary:parsed.summary||'',output:String(output),at:Date.now()};_pfw.results[p.id+':'+t.id]={score,summary:parsed.summary||'',output:String(output),at:Date.now()};_pfwSaveLocal();_pfwRenderTree();_pfwRenderActive();_pfwRenderTests();toast('Evaluation complete: '+score+'/100','success');}catch(e){toast('Evaluation failed: '+e.message,'error');}}
    async function _pfwRunAB(){const a=_pfw.nodes.get(Number(_pfw.activeId)),b=_pfw.nodes.get(Number(_pfw.compareId)),t=_pfw.tests[0];if(!a||!b||!t){toast('Select two branches and add a test first','warning');return;}if(typeof callAI!=='function'){toast('AI is not configured','warning');return;}try{const outA=await callAI(a.content,t.input,1400),outB=await callAI(b.content,t.input,1400);const judge='You are a blind A/B evaluator. Compare two outputs against the same test and quality bar. Do not favour A because it appears first. Return strict JSON with winner, scoreA, scoreB and reason.';const raw=await callAI(judge,'TEST INPUT:\n'+t.input+'\nQUALITY BAR:\n'+t.expected+'\n\nOUTPUT A:\n'+outA+'\n\nOUTPUT B:\n'+outB,1100);const parsed=JSON.parse(String(raw).replace(/^\`\`\`json\s*/i,'').replace(/\`\`\`$/,'').trim()),sa=Math.max(0,Math.min(100,Number(parsed.scoreA)||0)),sb=Math.max(0,Math.min(100,Number(parsed.scoreB)||0));_pfw.results[a.id]={score:sa,summary:'A/B result',output:String(outA),at:Date.now()};_pfw.results[b.id]={score:sb,summary:'A/B result',output:String(outB),at:Date.now()};_pfwSaveLocal();_pfwRenderTree();_pfwRenderCompare();$('#pfwAbResult').textContent='Winner: '+(String(parsed.winner).toUpperCase()==='B'?'B':'A')+' · A '+sa+' · B '+sb+' · '+(parsed.reason||'');}catch(e){toast('A/B evaluation failed: '+e.message,'error');}}
    async function _pfwMerge(){const a=_pfw.nodes.get(Number(_pfw.activeId)),b=_pfw.nodes.get(Number(_pfw.compareId));if(!a||!b||!confirm('Create a new branch by merging these prompts with AI?'))return;if(typeof callAI!=='function'){toast('AI is not configured','warning');return;}try{const merged=await callAI('You merge prompt variants. Preserve the strongest concrete instructions from both, remove contradictions and duplication, and return only the complete merged prompt.','PROMPT A:\n'+a.content+'\n\nPROMPT B:\n'+b.content,1800);const r=await fetch('/api/prompts/'+a.id+'/fork',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:(a.title||'Prompt')+' · Merge'})});if(!r.ok)throw new Error('Could not create merge branch');const d=await r.json(),p=await _pfwGetPrompt(d.id);const save=await fetch('/api/prompts/'+d.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:p.title,content:String(merged).trim(),description:p.description||'',categories:p.categories||[],tags:p.tags||[],folder_id:p.folder_id||null,colour_label:p.colour_label||'',rating:p.rating||0,notes:'Merged from #'+a.id+' and #'+b.id,chain_ids:p.chain_ids||[],variable_meta:p.variable_meta||{},chat_turns:p.chat_turns||[],role_id:p.role_id||null,status:'draft',parent_id:a.id,prompt_domain:p.prompt_domain||'',prompt_use_case:p.prompt_use_case||'',prompt_output_format:p.prompt_output_format||'',prompt_tone:p.prompt_tone||''})});if(!save.ok)throw new Error('Could not save merged branch');await loadPrompts();await _pfwLoadTree(_pfw.rootId);await _pfwSelect(d.id);toast('Merged branch created','success');}catch(e){toast('Merge failed: '+e.message,'error');}}
    function _pfwAddTest(){const name=prompt('Test name','New test case');if(!name)return;const input=prompt('Test input','');if(!input)return;const expected=prompt('Quality bar','The output should satisfy the intended task precisely.');_pfw.tests.push({id:'t-'+Date.now(),name,input,expected});_pfwSaveLocal();_pfwRenderTests();}
    function _pfwClose(){$('#promptForkingWorkspace')?.classList.remove('open');document.body.style.overflow='';}
    function _pfwRenderPicker(){const list=$('#pfwPromptPicker');if(!list)return;const q=($('#pfwPromptSearch')?.value||'').toLowerCase().trim();const items=state.prompts.filter(p=>!q||((p.title||'')+' '+(p.content||'')).toLowerCase().includes(q)).slice(0,80);list.innerHTML=items.map(p=>'<button type="button" class="pfw-picker-row" data-pfw-pick="'+p.id+'"><span class="material-symbols-outlined">description</span><span><b>'+escapeHtml(p.title||'Untitled')+'</b><small>'+escapeHtml((p.description||p.content||'').slice(0,100))+'</small></span></button>').join('')||'<div class="pfw-empty">No prompts found.</div>';list.querySelectorAll('[data-pfw-pick]').forEach(b=>b.addEventListener('click',()=>window.openPromptForkingWorkspace(Number(b.dataset.pfwPick))));}
    window.openPromptForkingWorkspace=async function(promptId){if(!state.isPremium){showPremiumModal();return;}const ws=$('#promptForkingWorkspace');if(!ws)return;ws.classList.add('open');document.body.style.overflow='hidden';const id=Number(promptId||state.detailId||0);if(!id){_pfw.rootId=null;_pfw.activeId=null;_pfw.nodes.clear();$('#pfwPicker')?.removeAttribute('hidden');$('#pfwMain')?.setAttribute('hidden','');_pfwRenderPicker();return;}$('#pfwPicker')?.setAttribute('hidden','');$('#pfwMain')?.removeAttribute('hidden');_pfw.rootId=id;await _pfwLoadTree(id);_pfwLoadLocal(id);_pfw.activeId=id;_pfw.compareId=null;_pfwRenderTree();_pfwRenderActive();_pfwRenderTests();_pfwSetMode('edit');};
    function initPromptForkingWorkspace(){const ws=$('#promptForkingWorkspace');if(!ws)return;$('#pfwCloseBtn')?.addEventListener('click',_pfwClose);$('#pfwNewForkBtn')?.addEventListener('click',_pfwCreateFork);$('#pfwSaveBtn')?.addEventListener('click',_pfwSave);$('#pfwDeleteBtn')?.addEventListener('click',_pfwDelete);$('#pfwArchiveBtn')?.addEventListener('click',_pfwArchive);$('#pfwWinnerBtn')?.addEventListener('click',_pfwMarkWinner);$('#pfwRunTestBtn')?.addEventListener('click',_pfwRunTest);$('#pfwRunABBtn')?.addEventListener('click',_pfwRunAB);$('#pfwMergeBtn')?.addEventListener('click',_pfwMerge);$('#pfwAddTestBtn')?.addEventListener('click',_pfwAddTest);$('#pfwCompareBtn')?.addEventListener('click',()=>{const ids=[..._pfw.nodes.keys()].filter(id=>id!==Number(_pfw.activeId));if(!ids.length)return;_pfw.compareId=_pfw.compareId&&ids.includes(Number(_pfw.compareId))?_pfw.compareId:ids[0];_pfwSetMode('compare');});ws.querySelectorAll('[data-pfw-mode]').forEach(b=>b.addEventListener('click',()=>_pfwSetMode(b.dataset.pfwMode)));$('#pfwPromptSearch')?.addEventListener('input',_pfwRenderPicker);$('#pfwTitleInput')?.addEventListener('input',_pfwRenderDiff);$('#pfwContentInput')?.addEventListener('input',_pfwRenderDiff);ws.addEventListener('keydown',e=>{if(e.key==='Escape')_pfwClose();});}

    /* ============================================================================
       LIBRARY ORGANIZER (formerly Library Pulse)
       Health scan of the whole library — duplicates, missing metadata, stale and
       thin prompts — plus fix actions: delete/keep duplicates, bulk-delete or
       mark-reviewed stale prompts, suggest-and-apply tags/categories via nearest
       neighbor (Jaccard over title+content, same scorer as Taxonomy auto-tag).
       data-view="pulse" | openPulseWorkspace() | initPulseWorkspace()
       ============================================================================ */

    function _pulseTokenSet(text) {
        return new Set((text || '').toLowerCase().slice(0, 400).match(/[a-z0-9]{3,}/g) || []);
    }

    function _pulseJaccard(sa, sb) {
        if (!sa.size || !sb.size) return 0;
        let inter = 0;
        sa.forEach(t => {
            if (sb.has(t)) inter++;
        });
        return inter / (sa.size + sb.size - inter);
    }

    const PULSE_FILTERS = [
        { key: 'all', label: 'All issues', icon: 'auto_awesome' },
        { key: 'untagged', label: 'Untagged', icon: 'label_important' },
        { key: 'uncategorised', label: 'No category', icon: 'category' },
        { key: 'undescribed', label: 'No description', icon: 'description' },
        { key: 'thin', label: 'Thin content', icon: 'compress' },
        { key: 'stale', label: 'Stale (90+ days)', icon: 'history' },
        { key: 'duplicates', label: 'Duplicates', icon: 'content_copy' },
    ];
    const PULSE_BADGE_LABEL = { untagged: 'No tags', uncategorised: 'No category', undescribed: 'No description', thin: 'Thin content', stale: 'Stale 90+ days' };

    let _pulseData = null;
    let _pulseFilter = 'all';
    let _pulseIndex = 0;
    let _pulseResolved = 0;

    function _pulseScoreFor(list, issues, dupCount) {
        const total = list.length || 1;
        const pct = arr => arr.length / total;
        return Math.max(0, Math.round(100 -
            pct(issues.untagged) * 25 -
            pct(issues.undescribed) * 20 -
            pct(issues.uncategorised) * 15 -
            pct(issues.thin) * 15 -
            Math.min(25, dupCount * 3)));
    }

    function _pulseLiveIssues() {
        const list = _pulseData.list;
        const metaEmpty = v => Array.isArray(v) ? !v.length : !String(v || '').trim();
        const cutoff = Date.now() - 90 * 24 * 3600 * 1000;
        const idSet = new Set(list.map(p => p.id));
        return {
            untagged: list.filter(p => metaEmpty(p.tags)),
            uncategorised: list.filter(p => metaEmpty(p.categories)),
            undescribed: list.filter(p => metaEmpty(p.description)),
            thin: list.filter(p => (p.content || '').trim().length < 40),
            stale: list.filter(p => {
                const d = Date.parse(p.updated_at || p.created_at || '');
                return !isNaN(d) && d < cutoff;
            }),
            duplicates: _pulseData.dupPairs.filter(([a, b]) => idSet.has(a.id) && idSet.has(b.id)),
        };
    }

    function _pulseAllQueue(issues) {
        const seen = new Map();
        ['untagged', 'uncategorised', 'undescribed', 'thin', 'stale'].forEach(key => {
            issues[key].forEach(p => {
                if (!seen.has(p.id)) seen.set(p.id, { p, keys: [] });
                seen.get(p.id).keys.push(key);
            });
        });
        return Array.from(seen.values()).sort((a, b) => b.keys.length - a.keys.length);
    }

    async function _pulseScan() {
        const scanBtn = $('#pulseRescanBtn');
        if (scanBtn) scanBtn.disabled = true;
        const stack = $('#pulseStack');
        if (stack) stack.innerHTML = '<div class="pulse-clear"><span class="material-symbols-outlined">hourglass_top</span><div class="pulse-card-title">Scanning…</div></div>';
        const meta = $('#pulseMeta');
        if (meta) meta.textContent = 'Scanning…';
        try {
            const data = await api('/prompts');
            const list = Array.isArray(data) ? data : (data.prompts || []);
            const capped = list.slice(0, 500).map(p => ({ p, set: _pulseTokenSet((p.title || '') + ' ' + (p.content || '')) }));
            const dupPairs = [];
            for (let i = 0; i < capped.length && dupPairs.length < 30; i++) {
                for (let j = i + 1; j < capped.length; j++) {
                    if (_pulseJaccard(capped[i].set, capped[j].set) >= 0.75) {
                        dupPairs.push([capped[i].p, capped[j].p]);
                        if (dupPairs.length >= 30) break;
                    }
                }
            }
            _pulseData = { list, dupPairs, cappedNote: list.length > 500 };
            _pulseResolved = 0;
            _pulseFilter = 'all';
            _pulseIndex = 0;
            _pulseAfterMutate();
        } catch (e) {
            if (stack) stack.innerHTML = '<div class="pulse-clear"><span class="material-symbols-outlined" style="color:var(--danger)">error</span><div class="pulse-card-title">Scan failed</div><p class="hint">' + escapeHtml(e.message) + '</p></div>';
        } finally {
            if (scanBtn) scanBtn.disabled = false;
        }
    }

    function _pulseRenderStats() {
        if (!_pulseData) return;
        const issues = _pulseLiveIssues();
        const score = _pulseScoreFor(_pulseData.list, issues, issues.duplicates.length);
        const scoreEl = $('#pulseScoreNum');
        if (scoreEl) scoreEl.textContent = score;
        const ring = $('#pulseRingFill');
        if (ring) {
            const c = 169.6;
            ring.style.strokeDashoffset = String(c - (c * score / 100));
            ring.style.stroke = score >= 80 ? '#16a34a' : (score >= 50 ? 'var(--accent)' : '#d97706');
        }
        const meta = $('#pulseMeta');
        if (meta) meta.textContent = _pulseData.list.length + ' prompts scanned' + (_pulseData.cappedNote ? ' (duplicate check capped at 500)' : '');
        const resolvedEl = $('#pulseResolvedCount');
        if (resolvedEl) resolvedEl.textContent = _pulseResolved + ' resolved this session';
    }

    function _pulseRenderRail() {
        const rail = $('#pulseRail');
        if (!rail || !_pulseData) return;
        const issues = _pulseLiveIssues();
        rail.innerHTML = PULSE_FILTERS.map(f => {
            const count = f.key === 'all' ? _pulseAllQueue(issues).length : issues[f.key].length;
            return '<button type="button" class="pulse-chip' + (f.key === _pulseFilter ? ' active' : '') + '" data-pulse-filter="' + f.key + '">' +
                '<span class="material-symbols-outlined">' + f.icon + '</span>' +
                '<span>' + f.label + '</span>' +
                '<span class="pulse-chip-count' + (count ? '' : ' ok') + '">' + count + '</span></button>';
        }).join('');
        rail.querySelectorAll('[data-pulse-filter]').forEach(btn => {
            btn.addEventListener('click', () => _pulseSetFilter(btn.dataset.pulseFilter));
        });
    }

    function _pulseSetFilter(key) {
        _pulseFilter = key;
        _pulseIndex = 0;
        _pulseRenderRail();
        _pulseRenderStack();
    }

    function _pulseSkip() {
        _pulseIndex++;
        _pulseRenderStack();
    }

    function _pulseAfterMutate() {
        _pulseRenderStats();
        _pulseRenderRail();
        _pulseRenderStack();
    }

    function _pulseOpenHandlers(root) {
        root.querySelectorAll('[data-pulse-open]').forEach(el => {
            el.addEventListener('click', () => {
                const id = parseInt(el.dataset.pulseOpen, 10);
                closePulseWorkspace();
                setTimeout(() => openDetail(id), 150);
            });
        });
    }

    function _pulseRenderStack() {
        const stack = $('#pulseStack');
        if (!stack || !_pulseData) return;
        const issues = _pulseLiveIssues();

        if (_pulseFilter === 'duplicates') {
            _pulseRenderDupStack(stack, issues.duplicates);
            return;
        }

        const queue = _pulseFilter === 'all' ? _pulseAllQueue(issues) : issues[_pulseFilter].map(p => ({ p, keys: [_pulseFilter] }));
        if (_pulseIndex >= queue.length) _pulseIndex = Math.max(0, queue.length - 1);

        if (!queue.length) {
            stack.innerHTML = '<div class="pulse-clear"><span class="material-symbols-outlined">task_alt</span>' +
                '<div class="pulse-card-title">All clear here</div><p class="hint">Nothing left to sort in this pile.</p></div>';
            return;
        }

        const entry = queue[_pulseIndex];
        const p = entry.p;
        const keys = entry.keys;
        const badges = keys.map(k => '<span class="pulse-badge' + (k === 'stale' ? ' pulse-badge-stale' : '') + '">' + PULSE_BADGE_LABEL[k] + '</span>').join('');

        let fixHtml = '';
        if (keys.includes('untagged')) {
            fixHtml += '<div class="pulse-fix"><div class="pulse-fix-label">Add a tag</div><div class="pulse-fix-row"><input type="text" placeholder="e.g. marketing" data-pulse-tag-input /><button type="button" class="btn btn-primary btn-xs" data-pulse-add-tag>Add</button></div></div>';
        }
        if (keys.includes('uncategorised')) {
            fixHtml += '<div class="pulse-fix"><div class="pulse-fix-label">Add a category</div><div class="pulse-fix-row"><input type="text" placeholder="e.g. Marketing" data-pulse-cat-input /><button type="button" class="btn btn-primary btn-xs" data-pulse-add-cat>Add</button></div></div>';
        }
        if (keys.includes('undescribed')) {
            fixHtml += '<div class="pulse-fix"><div class="pulse-fix-label">Write a description</div><div class="pulse-fix-row"><textarea placeholder="One line about what this prompt does…" data-pulse-desc-input></textarea></div><div class="pulse-fix-row"><button type="button" class="btn btn-primary btn-xs" data-pulse-save-desc>Save</button></div></div>';
        }

        const actions = ['<button type="button" class="btn btn-ghost" data-pulse-open="' + p.id + '"><span class="material-symbols-outlined">open_in_new</span> Open</button>'];
        if (keys.includes('stale')) {
            actions.push('<button type="button" class="btn btn-ghost" data-pulse-mark-reviewed><span class="material-symbols-outlined">check</span> Mark reviewed</button>');
        }
        actions.push('<button type="button" class="btn btn-danger" data-pulse-delete><span class="material-symbols-outlined">delete</span> Delete</button>');
        actions.push('<button type="button" class="btn btn-ghost" data-pulse-skip>Skip <span class="material-symbols-outlined">arrow_forward</span></button>');

        stack.innerHTML =
            '<div class="pulse-stack-progress"><div class="pulse-stack-progress-fill" style="width:' + Math.round((_pulseIndex / queue.length) * 100) + '%"></div></div>' +
            '<div class="pulse-card-active">' +
            '<div class="pulse-card-eyebrow">' + (_pulseIndex + 1) + ' of ' + queue.length + '</div>' +
            '<div class="pulse-card-title" data-pulse-open="' + p.id + '">' + escapeHtml(p.title || 'Untitled') + '</div>' +
            '<div class="pulse-card-preview">' + escapeHtml((p.content || '').slice(0, 220)) + '</div>' +
            '<div class="pulse-badges">' + badges + '</div>' +
            fixHtml +
            '<div class="pulse-actions">' + actions.join('') + '</div>' +
            '</div>';

        _pulseOpenHandlers(stack);
        stack.querySelector('[data-pulse-add-tag]')?.addEventListener('click', () => _pulseQuickAdd(p, 'tags'));
        stack.querySelector('[data-pulse-tag-input]')?.addEventListener('keydown', e => {
            if (e.key === 'Enter') { e.preventDefault(); _pulseQuickAdd(p, 'tags'); }
        });
        stack.querySelector('[data-pulse-add-cat]')?.addEventListener('click', () => _pulseQuickAdd(p, 'categories'));
        stack.querySelector('[data-pulse-cat-input]')?.addEventListener('keydown', e => {
            if (e.key === 'Enter') { e.preventDefault(); _pulseQuickAdd(p, 'categories'); }
        });
        stack.querySelector('[data-pulse-save-desc]')?.addEventListener('click', () => _pulseSaveDescription(p));
        stack.querySelector('[data-pulse-mark-reviewed]')?.addEventListener('click', () => _pulseMarkReviewed(p));
        stack.querySelector('[data-pulse-delete]')?.addEventListener('click', () => _pulseDeletePrompt(p));
        stack.querySelector('[data-pulse-skip]')?.addEventListener('click', () => _pulseSkip());
    }

    function _pulseRenderDupStack(stack, dupPairs) {
        if (_pulseIndex >= dupPairs.length) _pulseIndex = Math.max(0, dupPairs.length - 1);
        if (!dupPairs.length) {
            stack.innerHTML = '<div class="pulse-clear"><span class="material-symbols-outlined">task_alt</span>' +
                '<div class="pulse-card-title">No near-duplicates found</div><p class="hint">Your library is clean here.</p></div>';
            return;
        }
        const [a, b] = dupPairs[_pulseIndex];
        const col = (keep, other) => '<div class="pulse-dup-col">' +
            '<div class="pulse-dup-col-title" data-pulse-open="' + keep.id + '">' + escapeHtml(keep.title || 'Untitled') + '</div>' +
            '<div class="pulse-dup-col-preview">' + escapeHtml((keep.content || '').slice(0, 160)) + '</div>' +
            '<button type="button" class="btn btn-ghost btn-xs" data-pulse-keep-drop="' + escapeAttr(other.id) + '">Keep this, delete other</button></div>';
        stack.innerHTML =
            '<div class="pulse-stack-progress"><div class="pulse-stack-progress-fill" style="width:' + Math.round((_pulseIndex / dupPairs.length) * 100) + '%"></div></div>' +
            '<div class="pulse-card-active">' +
            '<div class="pulse-card-eyebrow">' + (_pulseIndex + 1) + ' of ' + dupPairs.length + ' possible duplicate' + (dupPairs.length !== 1 ? 's' : '') + '</div>' +
            '<div class="pulse-dup-compare">' + col(a, b) + '<div class="pulse-dup-vs">≈</div>' + col(b, a) + '</div>' +
            '<div class="pulse-actions"><button type="button" class="btn btn-ghost" data-pulse-skip>Not a duplicate, skip <span class="material-symbols-outlined">arrow_forward</span></button></div>' +
            '</div>';
        _pulseOpenHandlers(stack);
        stack.querySelectorAll('[data-pulse-keep-drop]').forEach(btn => {
            btn.addEventListener('click', () => _pulseDropDuplicate(parseInt(btn.dataset.pulseKeepDrop, 10)));
        });
        stack.querySelector('[data-pulse-skip]')?.addEventListener('click', () => _pulseSkip());
    }

    async function _pulseQuickAdd(p, field) {
        const stack = $('#pulseStack');
        const input = stack?.querySelector(field === 'tags' ? '[data-pulse-tag-input]' : '[data-pulse-cat-input]');
        const value = (input?.value || '').trim();
        if (!value) {
            toast('Type something first', 'warning');
            return;
        }
        const next = Array.isArray(p[field]) ? p[field].slice() : [];
        value.split(',').map(v => v.trim()).filter(Boolean).forEach(v => {
            if (!next.includes(v)) next.push(v);
        });
        try {
            await api(`/prompts/${p.id}`, { method: 'PUT', body: { ...p, [field]: next } });
            p[field] = next;
            _pulseResolved++;
            toast('Saved', 'success');
            _pulseAfterMutate();
        } catch {
            toast('Could not save', 'error');
        }
    }

    async function _pulseSaveDescription(p) {
        const stack = $('#pulseStack');
        const input = stack?.querySelector('[data-pulse-desc-input]');
        const value = (input?.value || '').trim();
        if (!value) {
            toast('Type a description first', 'warning');
            return;
        }
        try {
            await api(`/prompts/${p.id}`, { method: 'PUT', body: { ...p, description: value } });
            p.description = value;
            _pulseResolved++;
            toast('Saved', 'success');
            _pulseAfterMutate();
        } catch {
            toast('Could not save', 'error');
        }
    }

    async function _pulseMarkReviewed(p) {
        try {
            await api(`/prompts/${p.id}`, { method: 'PUT', body: p });
            p.updated_at = new Date().toISOString();
            _pulseResolved++;
            toast('Marked reviewed', 'success');
            _pulseAfterMutate();
        } catch {
            toast('Could not update', 'error');
        }
    }

    async function _pulseDeletePrompt(p) {
        if (!confirm('Delete "' + (p.title || 'Untitled') + '"? This can\'t be undone.')) return;
        try {
            await api(`/prompts/${p.id}`, { method: 'DELETE' });
            _pulseData.list = _pulseData.list.filter(x => x.id !== p.id);
            _pulseResolved++;
            toast('Deleted', 'success');
            _pulseAfterMutate();
        } catch {
            toast('Could not delete prompt', 'error');
        }
    }

    async function _pulseDropDuplicate(deleteId) {
        if (!confirm("Delete the other prompt in this pair? This can't be undone.")) return;
        try {
            await api(`/prompts/${deleteId}`, { method: 'DELETE' });
            _pulseData.list = _pulseData.list.filter(x => x.id !== deleteId);
            _pulseResolved++;
            toast('Duplicate removed', 'success');
            _pulseAfterMutate();
        } catch {
            toast('Could not delete prompt', 'error');
        }
    }

    window.openPulseWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#pulseWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'pulse'));
        _pulseScan();
    };

    function closePulseWorkspace() {
        $('#pulseWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initPulseWorkspace() {
        const ws = $('#pulseWorkspace');
        if (!ws) return;
        $('#closePulseBtn')?.addEventListener('click', closePulseWorkspace);
        $('#pulseRescanBtn')?.addEventListener('click', _pulseScan);
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closePulseWorkspace();
        });
    }


    /* ============================================================================
       PROMPT X-RAY WORKSPACE
       Deconstruct any prompt into its structural components — role, context,
       task, constraints, format, examples. Edit parts, reassemble, save.
       data-view="xray" | openXrayWorkspace() | initXrayWorkspace()
       ============================================================================ */

    const XRAY_PARTS = [{
            key: 'role',
            label: 'Role',
            icon: 'person'
        },
        {
            key: 'context',
            label: 'Context',
            icon: 'info'
        },
        {
            key: 'task',
            label: 'Task',
            icon: 'task_alt'
        },
        {
            key: 'constraints',
            label: 'Constraints',
            icon: 'block'
        },
        {
            key: 'format',
            label: 'Output Format',
            icon: 'format_list_bulleted'
        },
        {
            key: 'examples',
            label: 'Examples',
            icon: 'format_quote'
        },
        {
            key: 'other',
            label: 'Unclassified',
            icon: 'help_outline'
        },
    ];

    function _xrayRun() {
        const text = $('#xrayInput')?.value?.trim();
        if (!text) {
            toast('Paste a prompt first', 'warning');
            return;
        }
        const parts = _wsSplitComponents(text);
        const grid = $('#xrayGrid');
        if (!grid) return;
        grid.innerHTML = XRAY_PARTS.map(p => {
            const content = (parts[p.key] || []).join('\n');
            const present = !!content.trim();
            if (p.key === 'other' && !present) return '';
            return '<div class="xr-card' + (present ? '' : ' xr-missing') + '">' +
                '<div class="xr-card-head"><span class="material-symbols-outlined">' + p.icon + '</span>' +
                '<span>' + p.label + '</span>' +
                '<span class="xr-chip">' + (present ? 'Found' : 'Missing') + '</span>' +
                '<button class="icon-btn xr-copy" data-xr-part="' + p.key + '" title="Copy section"><span class="material-symbols-outlined" style="font-size:15px;">content_copy</span></button></div>' +
                '<textarea class="forge-input xr-text" data-xr-key="' + p.key + '" rows="3" placeholder="' +
                (present ? '' : 'Nothing detected — add your own ' + p.label.toLowerCase() + ' here…') + '">' + escapeHtml(content) + '</textarea>' +
                '</div>';
        }).join('');
        grid.querySelectorAll('.xr-copy').forEach(btn => {
            btn.addEventListener('click', async () => {
                const ta = grid.querySelector('.xr-text[data-xr-key="' + btn.dataset.xrPart + '"]');
                if (ta?.value.trim() && await copyToClipboard(ta.value.trim())) toast('Section copied', 'success');
            });
        });
        const actions = $('#xrayActions');
        if (actions) actions.style.display = 'flex';
    }

    function _xrayAssemble() {
        const parts = [];
        XRAY_PARTS.forEach(p => {
            const ta = document.querySelector('#xrayGrid .xr-text[data-xr-key="' + p.key + '"]');
            const v = ta?.value?.trim();
            if (v) parts.push('## ' + (p.key === 'other' ? 'Notes' : p.label) + '\n' + v);
        });
        return parts.join('\n\n');
    }

    window.openXrayWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#xrayWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'xray'));
        _wsFillPromptPicker('#xrayPicker');
        setTimeout(() => $('#xrayInput')?.focus(), 80);
    };

    function closeXrayWorkspace() {
        $('#xrayWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initXrayWorkspace() {
        const ws = $('#xrayWorkspace');
        if (!ws) return;
        $('#closeXrayBtn')?.addEventListener('click', closeXrayWorkspace);
        $('#xrayPicker')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#xrayPicker');
            if (p) {
                const el = $('#xrayInput');
                if (el) el.value = p.content || '';
            }
        });
        $('#xrayRunBtn')?.addEventListener('click', _xrayRun);
        $('#xrayCopyBtn')?.addEventListener('click', async () => {
            const text = _xrayAssemble();
            if (!text) {
                toast('Nothing to copy yet', 'warning');
                return;
            }
            if (await copyToClipboard(text)) toast('Structured prompt copied', 'success');
        });
        $('#xraySaveBtn')?.addEventListener('click', async () => {
            const text = _xrayAssemble();
            if (!text) {
                toast('Deconstruct a prompt first', 'warning');
                return;
            }
            const picked = _wsPickedPrompt('#xrayPicker');
            const title = ((picked?.title || 'Deconstructed prompt') + ' (structured)').slice(0, 120);
            const saved = await _wsSaveOrReplace({
                text,
                sourcePrompt: picked,
                newTitle: title,
                description: 'Restructured via Prompt X-Ray workspace',
                tags: 'x-ray',
            });
            if (saved?.id) {
                closeXrayWorkspace();
                setTimeout(() => openDetail(saved.id), 200);
            }
        });
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeXrayWorkspace();
        });
    }

    /* ============================================================================
       PROMPT SPLICER WORKSPACE
       Merge two prompts component-by-component: deconstruct both sides, pick
       which side supplies each part, assemble a hybrid. Offline.
       data-view="splice" | openSpliceWorkspace() | initSpliceWorkspace()
       ============================================================================ */

    let _splParts = null; // { a: {...}, b: {...} } after deconstruct

    function _splRun() {
        const a = $('#splInputA')?.value?.trim();
        const b = $('#splInputB')?.value?.trim();
        if (!a || !b) {
            toast('Fill both sides first', 'warning');
            return;
        }
        _splParts = {
            a: _wsSplitComponents(a),
            b: _wsSplitComponents(b)
        };
        const grid = $('#splGrid');
        if (!grid) return;
        grid.innerHTML = XRAY_PARTS.filter(p => p.key !== 'other').map(p => {
            const av = (_splParts.a[p.key] || []).join('\n');
            const bv = (_splParts.b[p.key] || []).join('\n');
            // Default pick: whichever side has content; A wins ties.
            const pick = av ? 'a' : (bv ? 'b' : 'none');
            const cell = (side, val) =>
                '<label class="spl-side' + (pick === side ? ' picked' : '') + (val ? '' : ' spl-empty') + '">' +
                '<input type="radio" name="spl-' + p.key + '" value="' + side + '"' + (pick === side ? ' checked' : '') + (val ? '' : ' disabled') + ' />' +
                '<span class="spl-side-tag">' + side.toUpperCase() + '</span>' +
                '<span class="spl-side-text">' + (val ? escapeHtml(val.length > 220 ? val.slice(0, 220) + '…' : val) : '<em>not present</em>') + '</span>' +
                '</label>';
            return '<div class="spl-row" data-spl-key="' + p.key + '">' +
                '<div class="spl-row-label"><span class="material-symbols-outlined">' + p.icon + '</span>' + p.label +
                (av || bv ? '' : ' <span class="xr-chip">Missing in both</span>') + '</div>' +
                '<div class="spl-pair">' + cell('a', av) + cell('b', bv) + '</div>' +
                '</div>';
        }).join('');
        const actions = $('#splActions');
        if (actions) actions.style.display = 'flex';
        _splPreview();
    }

    function _splAssemble() {
        if (!_splParts) return '';
        const parts = [];
        XRAY_PARTS.filter(p => p.key !== 'other').forEach(p => {
            const row = document.querySelector('#splGrid .spl-row[data-spl-key="' + p.key + '"]');
            const side = row?.querySelector('input:checked')?.value;
            if (!side || side === 'none') return;
            const val = (_splParts[side][p.key] || []).join('\n').trim();
            if (val) parts.push('## ' + p.label + '\n' + val);
        });
        return parts.join('\n\n');
    }

    function _splPreview() {
        const out = $('#splPreview');
        if (!out) return;
        // Sync .picked highlight with radio state
        $$('#splGrid .spl-side').forEach(l => l.classList.toggle('picked', l.querySelector('input')?.checked || false));
        const text = _splAssemble();
        out.innerHTML = text ? escapeHtml(text) : '<span class="hint">Pick components above to build the hybrid…</span>';
    }

    window.openSpliceWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#spliceWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'splice'));
        _wsFillPromptPicker('#splPickerA');
        _wsFillPromptPicker('#splPickerB');
    };

    function closeSpliceWorkspace() {
        $('#spliceWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initSpliceWorkspace() {
        const ws = $('#spliceWorkspace');
        if (!ws) return;
        $('#closeSpliceBtn')?.addEventListener('click', closeSpliceWorkspace);
        $('#splPickerA')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#splPickerA');
            if (p) {
                const el = $('#splInputA');
                if (el) el.value = p.content || '';
            }
        });
        $('#splPickerB')?.addEventListener('change', () => {
            const p = _wsPickedPrompt('#splPickerB');
            if (p) {
                const el = $('#splInputB');
                if (el) el.value = p.content || '';
            }
        });
        $('#splRunBtn')?.addEventListener('click', _splRun);
        $('#splGrid')?.addEventListener('change', _splPreview);
        $('#splCopyBtn')?.addEventListener('click', async () => {
            const text = _splAssemble();
            if (!text) {
                toast('Splice two prompts first', 'warning');
                return;
            }
            if (await copyToClipboard(text)) toast('Hybrid prompt copied', 'success');
        });
        $('#splSaveBtn')?.addEventListener('click', async () => {
            const text = _splAssemble();
            if (!text) {
                toast('Splice two prompts first', 'warning');
                return;
            }
            const pa = _wsPickedPrompt('#splPickerA'),
                pb = _wsPickedPrompt('#splPickerB');
            const title = ('Splice: ' + (pa?.title || 'A') + ' × ' + (pb?.title || 'B')).slice(0, 120);
            try {
                const result = await api('/prompts', {
                    method: 'POST',
                    body: {
                        title,
                        content: text,
                        description: 'Merged via Prompt Splicer workspace',
                        categories: 'Prompt Engineering',
                        tags: 'spliced'
                    }
                });
                await loadPrompts();
                await loadFilterOptions();
                toast('Saved: ' + title, 'success');
                closeSpliceWorkspace();
                if (result?.id) setTimeout(() => openDetail(result.id), 200);
            } catch {
                toast('Could not save', 'error');
            }
        });
        ws.addEventListener('keydown', e => {
            if (e.key === 'Escape') closeSpliceWorkspace();
        });
    }

    /* ============================================================================
       PROMPT BOARD WORKSPACE  ("Promptboard")
       Pinterest-style board/pin system: masonry feed, boards, favorites, tags.
       Boards live server-side (boards + board_pins tables); prompts are the
       full real prompt records from /api/prompts -- this workspace is a
       browsing/organising skin over the same data every other view uses.
       data-view="board" | openBoardWorkspace() | initBoardWorkspace()
       ============================================================================ */

    const PMB_COLOUR_NAMES = ['red', 'orange', 'yellow', 'green', 'teal', 'blue', 'indigo', 'violet', 'pink'];
    function _pmbColourName(record) {
        if (record && typeof record === 'object' && record.colour_label) return record.colour_label;
        const id = (record && typeof record === 'object') ? record.id : record;
        const s = String(id);
        let h = 0;
        for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
        return PMB_COLOUR_NAMES[h % PMB_COLOUR_NAMES.length];
    }
    function _pmbColor(record) {
        return 'var(--c-' + _pmbColourName(record) + '-soft)';
    }
    function _pmbSolidColor(record) {
        return 'var(--c-' + _pmbColourName(record) + ')';
    }
    function _pmbSwatchGridHtml(containerId, selected) {
        return '<div class="colour-swatches" id="' + containerId + '">' +
            '<div class="swatch none' + (!selected ? ' active' : '') + '" data-colour="" title="None"></div>' +
            PMB_COLOUR_NAMES.map(n => '<div class="swatch c-' + n + (selected === n ? ' active' : '') + '" data-colour="' + n + '" title="' + n.charAt(0).toUpperCase() + n.slice(1) + '"></div>').join('') +
            '</div>';
    }
    function _pmbBindSwatchGrid(containerId) {
        const picker = document.getElementById(containerId);
        if (!picker) return;
        picker.addEventListener('click', (e) => {
            const sw = e.target.closest('.swatch');
            if (!sw) return;
            picker.querySelectorAll('.swatch').forEach(s => s.classList.remove('active'));
            sw.classList.add('active');
        });
    }
    function _pmbSwatchValue(containerId) {
        return document.getElementById(containerId)?.querySelector('.swatch.active')?.dataset.colour || '';
    }

    let _pmbState = {
        view: 'feed',       // feed | boards | board | favorites | tags
        boards: [],
        prompts: [],
        boardPins: [],
        boardId: null,
        activeTag: null,
        search: '',
        sort: 'recent'
    };

    async function _pmbLoadAll() {
        try {
            const [boards, prompts] = await Promise.all([api('/boards'), api('/prompts')]);
            _pmbState.boards = boards;
            _pmbState.prompts = prompts;
        } catch {
            toast('Could not load Prompt Board', 'error');
        }
    }

    const _pmbBoardById = id => _pmbState.boards.find(b => b.id === id);

    function _pmbAllTags() {
        const map = new Map();
        _pmbState.prompts.forEach(p => (p.tags || []).forEach(t => map.set(t, (map.get(t) || 0) + 1)));
        return [...map.entries()].sort((a, b) => b[1] - a[1]);
    }

    function _pmbFiltered() {
        let list = _pmbState.view === 'board' ? _pmbState.boardPins.slice() : _pmbState.prompts.slice();
        if (_pmbState.view === 'favorites') list = list.filter(p => !!p.is_favorite);
        if (_pmbState.activeTag) list = list.filter(p => (p.tags || []).includes(_pmbState.activeTag));
        const q = _pmbState.search.trim().toLowerCase();
        if (q) {
            list = list.filter(p =>
                (p.title || '').toLowerCase().includes(q) ||
                (p.description || '').toLowerCase().includes(q) ||
                (p.content || '').toLowerCase().includes(q) ||
                (p.tags || []).some(t => t.toLowerCase().includes(q))
            );
        }
        const ts = p => new Date(p.updated_at || p.created_at || 0).getTime();
        if (_pmbState.sort === 'recent') list.sort((a, b) => ts(b) - ts(a));
        if (_pmbState.sort === 'oldest') list.sort((a, b) => ts(a) - ts(b));
        if (_pmbState.sort === 'alpha') list.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
        if (_pmbState.sort === 'used') list.sort((a, b) => (b.use_count || 0) - (a.use_count || 0));
        if (_pmbState.sort === 'starred') list.sort((a, b) => ((b.is_favorite ? 1 : 0) - (a.is_favorite ? 1 : 0)) || ts(b) - ts(a));
        return list;
    }
    const _pmbSortLabel = s => s === 'recent' ? 'Newest' : s === 'oldest' ? 'Oldest' : s === 'alpha' ? 'A-Z' : s === 'used' ? 'Most used' : 'Most starred';

    function _pmbRender() {
        _pmbRenderSidebar();
        _pmbRenderMain();
    }

    function _pmbRenderSidebar() {
        const el = $('#pmbSidebar');
        if (!el) return;
        const favCount = _pmbState.prompts.filter(p => p.is_favorite).length;
        el.innerHTML =
            '<nav class="pmb-nav" aria-label="Primary">' +
                '<button class="pmb-nav-item' + (_pmbState.view === 'feed' ? ' active' : '') + '" data-pmb="go-feed">' +
                    '<span class="material-symbols-outlined">home</span><span>Feed</span><span class="pmb-nav-count">' + _pmbState.prompts.length + '</span></button>' +
                '<button class="pmb-nav-item' + (_pmbState.view === 'boards' || _pmbState.view === 'board' ? ' active' : '') + '" data-pmb="go-boards">' +
                    '<span class="material-symbols-outlined">grid_view</span><span>Boards</span><span class="pmb-nav-count">' + _pmbState.boards.length + '</span></button>' +
                '<button class="pmb-nav-item' + (_pmbState.view === 'favorites' ? ' active' : '') + '" data-pmb="go-favorites">' +
                    '<span class="material-symbols-outlined">star</span><span>Favorites</span><span class="pmb-nav-count">' + favCount + '</span></button>' +
                '<button class="pmb-nav-item' + (_pmbState.view === 'tags' ? ' active' : '') + '" data-pmb="go-tags">' +
                    '<span class="material-symbols-outlined">sell</span><span>Tags</span><span class="pmb-nav-count">' + _pmbAllTags().length + '</span></button>' +
            '</nav>' +
            '<div class="pmb-sidebar-divider"></div>' +
            '<div class="pmb-sidebar-head"><h3>Your boards</h3>' +
                '<button data-pmb="open-add-board" aria-label="New board"><span class="material-symbols-outlined">add</span></button></div>' +
            '<nav class="pmb-nav" aria-label="Boards">' +
                _pmbState.boards.map(b =>
                    '<button class="pmb-board-nav-item' + (_pmbState.view === 'board' && _pmbState.boardId === b.id ? ' active' : '') + '" data-pmb="go-board" data-board-id="' + b.id + '">' +
                        '<span class="pmb-board-dot" style="background:' + _pmbColor(b) + '"></span>' +
                        '<span>' + escapeHtml(b.name) + '</span>' +
                        '<span class="pmb-board-count">' + (b.pin_count || 0) + '</span></button>'
                ).join('') +
            '</nav>';
        el.querySelectorAll('[data-pmb]').forEach(_pmbBind);
    }

    function _pmbRenderMain() {
        const main = $('#pmbMain');
        if (!main) return;
        if (_pmbState.view === 'feed') return _pmbViewFeed(main);
        if (_pmbState.view === 'boards') return _pmbViewBoards(main);
        if (_pmbState.view === 'board') return _pmbViewBoard(main);
        if (_pmbState.view === 'favorites') return _pmbViewFavorites(main);
        if (_pmbState.view === 'tags') return _pmbViewTags(main);
    }

    function _pmbPinCard(p) {
        const preview = (p.content || '').replace(/\s+/g, ' ').trim().slice(0, 200);
        const tags = (p.tags || []).slice(0, 2);
        const isFork = !!p.parent_id;
        const showUsage = (p.use_count || 0) >= 5;
        const hasFooter = tags.length || isFork || showUsage;
        return (
            '<article class="pmb-pin" style="--tint:' + _pmbColor(p) + ';--tint-solid:' + _pmbSolidColor(p) + '" data-pmb-pin="' + p.id + '" tabindex="0" role="button" aria-label="' + escapeHtml(p.title || 'Untitled') + '">' +
                '<div class="pmb-pin-save-wrap"><button class="pmb-pin-save-pill" data-pmb="add-to-board" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined" style="font-size:14px;">push_pin</span> Save</button></div>' +
                '<div class="pmb-pin-overlay">' +
                    '<button class="pmb-pin-action' + (p.is_favorite ? ' fav' : '') + '" data-pmb="toggle-fav" data-prompt-id="' + p.id + '" aria-label="Favorite" title="Favorite"><span class="material-symbols-outlined">star</span></button>' +
                    '<button class="pmb-pin-action" data-pmb="copy-prompt" data-prompt-id="' + p.id + '" aria-label="Copy prompt" title="Copy"><span class="material-symbols-outlined">content_copy</span></button>' +
                '</div>' +
                '<div class="pmb-pin-body">' +
                    '<div class="pmb-pin-cat"><span>' + (p.categories && p.categories[0] ? escapeHtml(p.categories[0]) : 'Unsorted') + '</span>' +
                        (p.is_favorite ? '<span class="pmb-pin-fav-badge"><span class="material-symbols-outlined">star</span></span>' : '') + '</div>' +
                    '<h3 class="pmb-pin-title">' + escapeHtml(p.title || 'Untitled') + '</h3>' +
                    (p.description ? '<p class="pmb-pin-outcome">' + escapeHtml(p.description) + '</p>' : '') +
                    '<p class="pmb-pin-preview">' + escapeHtml(preview) + '</p>' +
                '</div>' +
                (hasFooter ?
                    '<div class="pmb-pin-foot">' +
                        (isFork ? '<span class="pmb-pin-variant-badge"><span class="material-symbols-outlined" style="font-size:12px;">call_split</span>Fork</span>' : '') +
                        tags.map(t => '<span class="pmb-pin-tag">#' + escapeHtml(t) + '</span>').join('') +
                        (showUsage ? '<span class="pmb-pin-usage">Used ' + p.use_count + '&times;</span>' : '') +
                    '</div>' : '') +
            '</article>'
        );
    }

    function _pmbRelated(p) {
        const tags = new Set(p.tags || []);
        const cat = p.categories && p.categories[0];
        return _pmbState.prompts
            .filter(x => x.id !== p.id)
            .map(x => {
                let score = 0;
                if (cat && x.categories && x.categories[0] === cat) score += 2;
                (x.tags || []).forEach(t => { if (tags.has(t)) score += 1; });
                return { x, score };
            })
            .filter(r => r.score > 0)
            .sort((a, b) => b.score - a.score || new Date(b.x.updated_at || b.x.created_at || 0) - new Date(a.x.updated_at || a.x.created_at || 0))
            .slice(0, 6)
            .map(r => r.x);
    }

    function _pmbBoardCard(b) {
        const count = b.pin_count || 0;
        const sub = b.description ? escapeHtml(b.description) : (count + ' prompt' + (count === 1 ? '' : 's'));
        return (
            '<button class="pmb-board-card" data-pmb="go-board" data-board-id="' + b.id + '">' +
                '<div class="pmb-board-cover" style="--tint:' + _pmbColor(b) + ';--tint-solid:' + _pmbSolidColor(b) + '">' +
                    '<div class="pmb-board-cover-count">' + count + ' prompt' + (count === 1 ? '' : 's') + '</div>' +
                    '<div class="pmb-board-cover-name">' + escapeHtml(b.name) + '</div>' +
                '</div>' +
                '<div class="pmb-board-meta"><div class="pmb-board-name">' + escapeHtml(b.name) + '</div><div class="pmb-board-sub">' + sub + '</div></div>' +
            '</button>'
        );
    }

    function _pmbEmpty(icon, title, body, actions) {
        return (
            '<div class="pmb-empty"><div class="pmb-empty-icon"><span class="material-symbols-outlined">' + icon + '</span></div>' +
                '<h2>' + escapeHtml(title) + '</h2><p>' + body + '</p>' +
                '<div class="pmb-empty-actions">' +
                    (actions || []).map(a =>
                        '<button class="btn ' + (a.cls || 'btn-ghost') + '" data-pmb="' + a.action + '"' + (a.boardId ? ' data-board-id="' + a.boardId + '"' : '') + '>' + a.label + '</button>'
                    ).join('') +
                '</div></div>'
        );
    }

    function _pmbViewFeed(main) {
        const list = _pmbFiltered();
        const tags = _pmbAllTags().slice(0, 8);
        let html = '<div class="pmb-page-head"><div><h1 class="pmb-page-title">Your prompt feed</h1>' +
            '<p class="pmb-page-sub">Everything in your library, most recent first.</p></div>' +
            '<div class="pmb-page-head-actions"><button class="pmb-chip" data-pmb="cycle-sort"><span class="material-symbols-outlined" style="font-size:14px;">sort</span><span>' + _pmbSortLabel(_pmbState.sort) + '</span></button></div></div>';
        if (_pmbState.search && !list.length) {
            main.innerHTML = html + _pmbEmpty('search', 'No prompts match that search', 'Nothing matches &ldquo;' + escapeHtml(_pmbState.search) + '&rdquo;. Try another word.', [{ label: 'Clear search', action: 'clear-search', cls: 'btn-accent' }]);
            _pmbBindMain(main); return;
        }
        if (!list.length) {
            main.innerHTML = html + _pmbEmpty('inbox', 'Your feed is empty', 'Add your first prompt to get started.', [{ label: 'Add a prompt', action: 'open-add-prompt', cls: 'btn-accent' }]);
            _pmbBindMain(main); return;
        }
        if (tags.length) {
            html += '<div class="pmb-chip-row"><button class="pmb-chip' + (!_pmbState.activeTag ? ' active' : '') + '" data-pmb="filter-tag" data-tag="">All</button>' +
                tags.map(([t, c]) => '<button class="pmb-chip' + (_pmbState.activeTag === t ? ' active' : '') + '" data-pmb="filter-tag" data-tag="' + escapeHtml(t) + '">#' + escapeHtml(t) + ' <span style="opacity:.55">' + c + '</span></button>').join('') +
                '</div>';
        }
        html += '<div class="pmb-masonry">' + list.map(_pmbPinCard).join('') + '</div>';
        main.innerHTML = html;
        _pmbBindMain(main);
    }

    function _pmbViewBoards(main) {
        let html = '<div class="pmb-page-head"><div><h1 class="pmb-page-title">Your boards</h1><p class="pmb-page-sub">Group prompts by what they are for.</p></div>' +
            '<div class="pmb-page-head-actions"><button class="btn btn-accent" data-pmb="open-add-board"><span class="material-symbols-outlined">add</span> New board</button></div></div>';
        if (!_pmbState.boards.length) {
            html += _pmbEmpty('dashboard_customize', 'No boards yet', 'Boards let you group related prompts. Start with one.', [{ label: 'Create a board', action: 'open-add-board', cls: 'btn-accent' }]);
        } else {
            html += '<div class="pmb-board-grid">' + _pmbState.boards.map(_pmbBoardCard).join('') + '</div>';
        }
        main.innerHTML = html;
        _pmbBindMain(main);
    }

    async function _pmbGoBoard(id) {
        _pmbState.view = 'board';
        _pmbState.boardId = id;
        _pmbState.activeTag = null;
        _pmbState.boardPins = [];
        _pmbRender();
        try {
            _pmbState.boardPins = await api('/boards/' + id + '/pins');
        } catch {
            toast('Could not load board', 'error');
        }
        if (_pmbState.view === 'board' && _pmbState.boardId === id) _pmbRenderMain();
        await _wsFillPromptPicker('#pmbPinPicker');
    }

    function _pmbViewBoard(main) {
        const b = _pmbBoardById(_pmbState.boardId);
        if (!b) { _pmbState.view = 'boards'; return _pmbViewBoards(main); }
        const list = _pmbFiltered();
        let html = '<button class="pmb-back-btn" data-pmb="go-boards"><span class="material-symbols-outlined" style="font-size:16px;">chevron_left</span> All boards</button>' +
            '<div class="pmb-board-header">' +
                '<div class="pmb-board-header-cover" style="--tint:' + _pmbColor(b) + ';--tint-solid:' + _pmbSolidColor(b) + '">' + escapeHtml((b.name || '?').slice(0, 1).toUpperCase()) + '</div>' +
                '<div class="pmb-board-header-info"><h1>' + escapeHtml(b.name) + '</h1>' +
                '<p>' + escapeHtml(b.description || '') + (b.description ? ' &middot; ' : '') + list.length + ' prompt' + (list.length === 1 ? '' : 's') + '</p>' +
                '<div class="pmb-pin-picker-row">' +
                    '<select id="pmbPinPicker" class="forge-input pmb-select"><option value="">Pin an existing prompt&hellip;</option></select>' +
                    '<button class="btn btn-ghost" id="pmbPinExistingBtn">Pin</button>' +
                '</div>' +
                '<div class="pmb-board-header-actions">' +
                    '<button class="btn btn-accent" data-pmb="open-add-prompt" data-board-id="' + b.id + '"><span class="material-symbols-outlined">add</span> New prompt</button>' +
                    '<button class="btn btn-ghost" data-pmb="rename-board" data-board-id="' + b.id + '"><span class="material-symbols-outlined">edit</span> Rename</button>' +
                    '<button class="btn btn-ghost" data-pmb="duplicate-board" data-board-id="' + b.id + '"><span class="material-symbols-outlined">content_copy</span> Duplicate</button>' +
                    '<button class="btn btn-ghost" data-pmb="export-board" data-board-id="' + b.id + '"><span class="material-symbols-outlined">ios_share</span> Export</button>' +
                    '<button class="btn btn-danger" data-pmb="delete-board" data-board-id="' + b.id + '"><span class="material-symbols-outlined">delete</span> Delete</button>' +
                '</div></div></div>';
        if (!list.length) {
            html += _pmbEmpty('inbox', 'Nothing pinned yet', 'Pin an existing prompt above, or create a new one for this board.', [{ label: 'New prompt', action: 'open-add-prompt', cls: 'btn-accent', boardId: b.id }]);
        } else {
            html += '<div class="pmb-masonry">' + list.map(p => _pmbPinCard(p).replace('<div class="pmb-pin-overlay">', '<div class="pmb-pin-overlay"><button class="pmb-pin-action" data-pmb="unpin" data-prompt-id="' + p.id + '" aria-label="Remove from board" title="Remove from board"><span class="material-symbols-outlined">close</span></button>')).join('') + '</div>';
        }
        main.innerHTML = html;
        _pmbBindMain(main);
        $('#pmbPinExistingBtn')?.addEventListener('click', _pmbPinExisting);
    }

    async function _pmbPinExisting() {
        const p = _wsPickedPrompt('#pmbPinPicker');
        if (!p) { toast('Pick a prompt to pin', 'warning'); return; }
        try {
            await api('/boards/' + _pmbState.boardId + '/pins', { method: 'POST', body: { prompt_id: p.id } });
            toast('Pinned to board', 'success');
            const board = _pmbBoardById(_pmbState.boardId);
            if (board) board.pin_count = (board.pin_count || 0) + 1;
            await _pmbGoBoard(_pmbState.boardId);
        } catch {
            toast('Could not pin prompt', 'error');
        }
    }

    function _pmbViewFavorites(main) {
        const list = _pmbFiltered();
        let html = '<div class="pmb-page-head"><div><h1 class="pmb-page-title">Favorites</h1><p class="pmb-page-sub">The prompts you reach for most.</p></div></div>';
        if (!list.length) {
            html += _pmbEmpty('star', 'No favorites yet', 'Star any prompt to pin it here for quick access.', [{ label: 'Browse your feed', action: 'go-feed', cls: 'btn-accent' }]);
        } else {
            html += '<div class="pmb-masonry">' + list.map(_pmbPinCard).join('') + '</div>';
        }
        main.innerHTML = html;
        _pmbBindMain(main);
    }

    function _pmbViewTags(main) {
        const tags = _pmbAllTags();
        let html = '<div class="pmb-page-head"><div><h1 class="pmb-page-title">Tags</h1><p class="pmb-page-sub">Every tag across your library, most used first.</p></div></div>';
        if (!tags.length) {
            html += _pmbEmpty('sell', 'No tags yet', 'Tags are added when you create or edit a prompt.', [{ label: 'Add a prompt', action: 'open-add-prompt', cls: 'btn-accent' }]);
        } else {
            html += '<div class="pmb-tag-grid">' + tags.map(([t, c]) =>
                '<button class="pmb-tag-card" data-pmb="go-tag" data-tag="' + escapeHtml(t) + '"><span class="pmb-tag-card-name">' + escapeHtml(t) + '</span><span class="pmb-tag-card-count">' + c + '</span></button>'
            ).join('') + '</div>';
        }
        main.innerHTML = html;
        _pmbBindMain(main);
    }

    function _pmbBindMain(main) {
        main.querySelectorAll('[data-pmb]').forEach(_pmbBind);
        main.querySelectorAll('[data-pmb-pin]').forEach(card => {
            card.addEventListener('click', e => {
                if (e.target.closest('[data-pmb]')) return;
                _pmbOpenPinDetail(Number(card.dataset.pmbPin));
            });
            card.addEventListener('keydown', e => {
                if (e.key === 'Enter' && !e.target.closest('[data-pmb]')) _pmbOpenPinDetail(Number(card.dataset.pmbPin));
            });
        });
    }

    function _pmbOpenModal(html) {
        const modal = $('#pmbModal');
        const card = $('#pmbModalCard');
        if (!modal || !card) return;
        card.innerHTML = html;
        modal.hidden = false;
        document.body.style.overflow = 'hidden';
        card.querySelectorAll('[data-pmb-close]').forEach(el => el.addEventListener('click', _pmbCloseModal));
        card.querySelectorAll('[data-pmb]').forEach(_pmbBind);
        setTimeout(() => card.querySelector('input, textarea')?.focus(), 30);
    }
    function _pmbCloseModal() {
        const modal = $('#pmbModal');
        if (!modal) return;
        modal.hidden = true;
        $('#pmbModalCard').innerHTML = '';
        document.body.style.overflow = '';
    }

    function _pmbOpenPinDetail(id) {
        const p = _pmbState.prompts.find(x => x.id === id) || _pmbState.boardPins.find(x => x.id === id);
        if (!p) return;
        const uses = p.use_count || 0;
        const meta = [uses === 0 ? 'Not used yet' : ('Used ' + uses + (uses === 1 ? ' time' : ' times'))];
        if (p.created_at) meta.push('Added ' + new Date(p.created_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }));
        const related = _pmbRelated(p);
        const pmbVars = detectVariables(p.content);
        _pmbOpenModal(
            '<div class="pmb-modal-head"><h2>Prompt</h2><button class="icon-btn" data-pmb-close aria-label="Close"><span class="material-symbols-outlined">close</span></button></div>' +
            '<div class="pmb-modal-body">' +
                '<div class="pmb-prompt-hero" style="--tint:' + _pmbColor(p) + '">' +
                    '<div class="pmb-prompt-hero-cat">' + (p.categories && p.categories[0] ? escapeHtml(p.categories[0]) : 'Unsorted') + (p.parent_id ? ' &middot; Fork' : '') + '</div>' +
                    '<h2>' + escapeHtml(p.title || 'Untitled') + '</h2>' +
                    (p.description ? '<p class="pmb-prompt-hero-outcome">' + escapeHtml(p.description) + '</p>' : '') +
                    '<div class="pmb-prompt-hero-meta">' + meta.map((m, i) => (i > 0 ? '<span class="pmb-dot"></span>' : '') + '<span>' + escapeHtml(m) + '</span>').join('') + '</div>' +
                    '<div class="pmb-prompt-hero-tags">' + (p.tags || []).map(t => '<span class="pmb-pin-tag">#' + escapeHtml(t) + '</span>').join('') + '</div>' +
                '</div>' +
                (pmbVars.length ?
                    '<div class="pmb-var-panel" id="pmbVarPanel"><h3 class="pmb-related-title">Fill in variables</h3><div class="pmb-var-grid">' +
                        pmbVars.map(v => '<div class="pmb-var-field"><label>' + escapeHtml(v) + '</label><input type="text" class="forge-input pmb-var-input" data-pmb-var="' + escapeAttr(v) + '" placeholder="' + escapeAttr(v) + '"></div>').join('') +
                    '</div></div>' : '') +
                '<div class="pmb-prompt-block" id="pmbPromptBlock">' + escapeHtml(p.content || '') + '</div>' +
                '<div class="pmb-prompt-actions">' +
                    (pmbVars.length ?
                        '<button class="btn btn-accent" data-pmb="copy-filled" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">content_copy</span> Copy filled</button>' :
                        '<button class="btn btn-accent" data-pmb="copy-prompt" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">content_copy</span> Copy</button>') +
                    '<button class="btn btn-ghost" data-pmb="toggle-fav" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">star</span> ' + (p.is_favorite ? 'Favorited' : 'Favorite') + '</button>' +
                    '<button class="btn btn-ghost" data-pmb="fork-prompt" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">call_split</span> Fork</button>' +
                    '<button class="btn btn-ghost" data-pmb="add-to-board" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">push_pin</span> Add to board</button>' +
                    '<button class="btn btn-ghost" data-pmb="edit-prompt" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">edit</span> Edit</button>' +
                    '<button class="btn btn-danger" data-pmb="delete-prompt" data-prompt-id="' + p.id + '"><span class="material-symbols-outlined">delete</span> Delete</button>' +
                '</div>' +
                (related.length ? '<div class="pmb-related"><h3 class="pmb-related-title">More like this</h3><div class="pmb-related-feed">' + related.map(_pmbPinCard).join('') + '</div></div>' : '') +
            '</div>'
        );
        $('#pmbModalCard')?.querySelectorAll('[data-pmb-pin]').forEach(card => {
            card.addEventListener('click', e => {
                if (e.target.closest('[data-pmb]')) return;
                _pmbOpenPinDetail(Number(card.dataset.pmbPin));
            });
        });
        document.querySelectorAll('#pmbVarPanel .pmb-var-input').forEach(inp => {
            inp.addEventListener('input', () => {
                const map = {};
                document.querySelectorAll('#pmbVarPanel .pmb-var-input').forEach(i2 => { map[i2.dataset.pmbVar] = i2.value || ('{{' + i2.dataset.pmbVar + '}}'); });
                const block = $('#pmbPromptBlock');
                if (block) block.textContent = replaceVariables(p.content || '', map);
            });
        });
    }

    function _pmbOpenPromptSheet(promptId, presetBoardId) {
        const editing = promptId ? _pmbState.prompts.find(p => p.id === promptId) : null;
        const title = editing ? 'Edit prompt' : 'Add a prompt';
        _pmbOpenModal(
            '<div class="pmb-modal-head"><h2>' + title + '</h2><button class="icon-btn" data-pmb-close aria-label="Close"><span class="material-symbols-outlined">close</span></button></div>' +
            '<div class="pmb-modal-body">' +
                '<div class="pmb-field"><label for="pmb-title">Title</label>' +
                    '<input id="pmb-title" class="forge-input" type="text" placeholder="e.g. Blog post outline generator" value="' + (editing ? escapeHtml(editing.title || '') : '') + '" maxlength="120"></div>' +
                '<div class="pmb-field"><label for="pmb-outcome">Outcome</label>' +
                    '<input id="pmb-outcome" class="forge-input" type="text" placeholder="One line: what does this prompt do?" value="' + (editing ? escapeHtml(editing.description || '') : '') + '" maxlength="200">' +
                    '<div class="pmb-hint">Shown under the title in the feed.</div></div>' +
                '<div class="pmb-field"><label for="pmb-content">Prompt text</label>' +
                    '<textarea id="pmb-content" class="forge-input pmb-textarea tall" placeholder="Paste or write the full prompt here&hellip;">' + (editing ? escapeHtml(editing.content || '') : '') + '</textarea></div>' +
                '<div class="pmb-field"><label for="pmb-tags">Tags</label>' +
                    '<input id="pmb-tags" class="forge-input" type="text" placeholder="writing, blog, seo" value="' + (editing ? escapeHtml((editing.tags || []).join(', ')) : '') + '">' +
                    '<div class="pmb-hint">Comma separated.</div></div>' +
                '<div class="pmb-field"><label>Colour</label>' + _pmbSwatchGridHtml('pmbPromptColour', editing ? (editing.colour_label || '') : '') + '</div>' +
            '</div>' +
            '<div class="pmb-modal-foot"><button class="btn btn-ghost" data-pmb-close>Cancel</button>' +
                '<button class="btn btn-accent" data-pmb="save-prompt" data-prompt-id="' + (editing ? editing.id : '') + '" data-board-id="' + (presetBoardId || '') + '">' + (editing ? 'Save changes' : 'Add to library') + '</button></div>'
        );
        _pmbBindSwatchGrid('pmbPromptColour');
    }

    async function _pmbSavePrompt(promptId, presetBoardId) {
        const titleEl = $('#pmb-title'), outcomeEl = $('#pmb-outcome'), contentEl = $('#pmb-content'), tagsEl = $('#pmb-tags');
        const title = (titleEl?.value || '').trim();
        const content = (contentEl?.value || '').trim();
        if (!title) { toast('Title is required', 'warning'); titleEl?.focus(); return; }
        if (!content) { toast('Prompt text is required', 'warning'); contentEl?.focus(); return; }
        const tags = (tagsEl?.value || '').split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
        const body = { title, description: (outcomeEl?.value || '').trim(), content, tags, colour_label: _pmbSwatchValue('pmbPromptColour') };
        try {
            if (promptId) {
                await api('/prompts/' + promptId, { method: 'PUT', body });
                toast('Prompt updated', 'success');
            } else {
                const result = await api('/prompts', { method: 'POST', body });
                if (presetBoardId && result?.id) {
                    await api('/boards/' + presetBoardId + '/pins', { method: 'POST', body: { prompt_id: result.id } });
                }
                toast('Added to library', 'success');
            }
            _pmbCloseModal();
            await _pmbLoadAll();
            if (_pmbState.view === 'board' && _pmbState.boardId) await _pmbGoBoard(_pmbState.boardId);
            else _pmbRender();
        } catch {
            toast('Could not save prompt', 'error');
        }
    }

    function _pmbOpenBoardSheet(boardId) {
        const editing = boardId ? _pmbBoardById(boardId) : null;
        _pmbOpenModal(
            '<div class="pmb-modal-head"><h2>' + (editing ? 'Rename board' : 'New board') + '</h2><button class="icon-btn" data-pmb-close aria-label="Close"><span class="material-symbols-outlined">close</span></button></div>' +
            '<div class="pmb-modal-body">' +
                '<div class="pmb-field"><label for="pmb-board-name">Name</label>' +
                    '<input id="pmb-board-name" class="forge-input" type="text" placeholder="e.g. Coding" value="' + (editing ? escapeHtml(editing.name) : '') + '" maxlength="80"></div>' +
                '<div class="pmb-field"><label for="pmb-board-desc">Description <span style="font-weight:400;">(optional)</span></label>' +
                    '<input id="pmb-board-desc" class="forge-input" type="text" placeholder="What goes in this board?" value="' + (editing ? escapeHtml(editing.description || '') : '') + '" maxlength="140"></div>' +
                '<div class="pmb-field"><label>Colour</label>' + _pmbSwatchGridHtml('pmbBoardColour', editing ? (editing.colour_label || '') : '') + '</div>' +
            '</div>' +
            '<div class="pmb-modal-foot"><button class="btn btn-ghost" data-pmb-close>Cancel</button>' +
                '<button class="btn btn-accent" data-pmb="save-board" data-board-id="' + (editing ? editing.id : '') + '">' + (editing ? 'Save changes' : 'Create board') + '</button></div>'
        );
        _pmbBindSwatchGrid('pmbBoardColour');
    }

    async function _pmbSaveBoard(boardId) {
        const nameEl = $('#pmb-board-name'), descEl = $('#pmb-board-desc');
        const name = (nameEl?.value || '').trim();
        if (!name) { toast('Name is required', 'warning'); nameEl?.focus(); return; }
        const description = (descEl?.value || '').trim();
        const colour_label = _pmbSwatchValue('pmbBoardColour');
        try {
            if (boardId) {
                await api('/boards/' + boardId, { method: 'PUT', body: { name, description, colour_label } });
                toast('Board updated', 'success');
            } else {
                await api('/boards', { method: 'POST', body: { name, description, colour_label } });
                toast('Board created', 'success');
            }
            _pmbCloseModal();
            await _pmbLoadAll();
            _pmbRender();
        } catch {
            toast('Could not save board', 'error');
        }
    }

    function _pmbOpenBoardPicker(promptId) {
        const p = _pmbState.prompts.find(x => x.id === promptId);
        if (!p) return;
        _pmbOpenModal(
            '<div class="pmb-modal-head"><h2>Add to board</h2><button class="icon-btn" data-pmb-close aria-label="Close"><span class="material-symbols-outlined">close</span></button></div>' +
            '<div class="pmb-modal-body">' +
                (_pmbState.boards.length ?
                    '<div class="pmb-board-picker">' + _pmbState.boards.map(b =>
                        '<button class="pmb-board-pick-item" data-pmb="assign-board" data-prompt-id="' + p.id + '" data-board-id="' + b.id + '">' +
                            '<span class="pmb-board-pick-dot" style="background:' + _pmbColor(b) + '"></span>' +
                            '<span class="pmb-board-pick-info"><span class="pmb-board-pick-name">' + escapeHtml(b.name) + '</span>' +
                            '<span class="pmb-board-pick-meta">' + (b.pin_count || 0) + ' prompt' + ((b.pin_count || 0) === 1 ? '' : 's') + '</span></span>' +
                        '</button>'
                    ).join('') + '</div>'
                    : '<p class="pmb-hint">No boards yet.</p>') +
            '</div>' +
            '<div class="pmb-modal-foot"><button class="btn btn-ghost" data-pmb="open-add-board-from-picker">New board</button>' +
                '<button class="btn btn-accent" data-pmb-close>Done</button></div>'
        );
    }

    function _pmbBind(el) {
        if (el._pmbBound) return;
        el._pmbBound = true;
        el.addEventListener('click', async e => {
            const action = el.dataset.pmb;
            const promptId = Number(el.dataset.promptId) || null;
            const boardId = el.dataset.boardId ? Number(el.dataset.boardId) : null;
            const tag = el.dataset.tag;
            switch (action) {
                case 'go-feed': _pmbState.view = 'feed'; _pmbState.boardId = null; _pmbState.activeTag = null; _pmbRender(); break;
                case 'go-boards': _pmbState.view = 'boards'; _pmbState.boardId = null; _pmbRender(); break;
                case 'go-favorites': _pmbState.view = 'favorites'; _pmbState.boardId = null; _pmbState.activeTag = null; _pmbRender(); break;
                case 'go-tags': _pmbState.view = 'tags'; _pmbState.boardId = null; _pmbRender(); break;
                case 'go-tag': _pmbState.activeTag = tag; _pmbState.view = 'feed'; _pmbState.boardId = null; _pmbRender(); break;
                case 'go-board': await _pmbGoBoard(boardId); _pmbRenderSidebar(); break;
                case 'filter-tag': _pmbState.activeTag = tag || null; _pmbRenderMain(); break;
                case 'cycle-sort': {
                    const order = ['recent', 'oldest', 'alpha', 'used', 'starred'];
                    _pmbState.sort = order[(order.indexOf(_pmbState.sort) + 1) % order.length];
                    _pmbRenderMain();
                    break;
                }
                case 'clear-search': {
                    _pmbState.search = '';
                    const input = $('#pmbSearchInput'); if (input) input.value = '';
                    $('#pmbSearchClear')?.classList.remove('visible');
                    _pmbRenderMain();
                    break;
                }
                case 'open-add-prompt': _pmbOpenPromptSheet(null, boardId); break;
                case 'open-add-board': _pmbOpenBoardSheet(); break;
                case 'edit-prompt': _pmbCloseModal(); setTimeout(() => _pmbOpenPromptSheet(promptId), 160); break;
                case 'save-prompt': _pmbSavePrompt(promptId, boardId); break;
                case 'rename-board': _pmbOpenBoardSheet(boardId); break;
                case 'save-board': _pmbSaveBoard(boardId); break;
                case 'delete-board': {
                    const b = _pmbBoardById(boardId);
                    if (!b) return;
                    if (!confirm('Delete "' + b.name + '"? Pins are removed, prompts are not.')) return;
                    try {
                        await api('/boards/' + boardId, { method: 'DELETE' });
                        toast('Board deleted', 'success');
                        _pmbState.view = 'boards'; _pmbState.boardId = null;
                        await _pmbLoadAll();
                        _pmbRender();
                    } catch { toast('Could not delete board', 'error'); }
                    break;
                }
                case 'duplicate-board': {
                    try {
                        const result = await api('/boards/' + boardId + '/duplicate', { method: 'POST' });
                        toast('Board duplicated', 'success');
                        await _pmbLoadAll();
                        if (result?.id) {
                            await _pmbGoBoard(result.id);
                            _pmbRenderSidebar();
                        }
                    } catch { toast('Could not duplicate board', 'error'); }
                    break;
                }
                case 'export-board': {
                    if (!boardId) { toast('Could not export board', 'error'); break; }
                    window.location.href = API_BASE + '/boards/' + boardId + '/export';
                    break;
                }
                case 'toggle-fav': {
                    try {
                        const res = await api('/prompts/' + promptId + '/favorite', { method: 'POST' });
                        const p = _pmbState.prompts.find(x => x.id === promptId);
                        if (p) p.is_favorite = res.is_favorite;
                        const bp = _pmbState.boardPins.find(x => x.id === promptId);
                        if (bp) bp.is_favorite = res.is_favorite;
                        toast(res.is_favorite ? 'Added to favorites' : 'Removed from favorites', 'success');
                        if ($('#pmbModal') && !$('#pmbModal').hidden) _pmbOpenPinDetail(promptId);
                        _pmbRenderMain(); _pmbRenderSidebar();
                    } catch { toast('Could not update favorite', 'error'); }
                    break;
                }
                case 'copy-prompt': window.PL_useFromCard(promptId); break;
                case 'copy-filled': {
                    const p2 = _pmbState.prompts.find(x => x.id === promptId) || _pmbState.boardPins.find(x => x.id === promptId);
                    if (!p2) break;
                    const map = {};
                    document.querySelectorAll('#pmbVarPanel .pmb-var-input').forEach(inp => { map[inp.dataset.pmbVar] = inp.value.trim() || ('[' + inp.dataset.pmbVar + ']'); });
                    const filled = replaceVariables(p2.content || '', map);
                    copyToClipboard(filled).then(ok => {
                        if (ok) {
                            api('/prompts/' + promptId + '/use', { method: 'POST' }).catch(() => {});
                            toast('Copied with variables filled', 'success');
                        }
                    });
                    break;
                }
                case 'fork-prompt': {
                    try {
                        const result = await api('/prompts/' + promptId + '/fork', { method: 'POST', body: {} });
                        toast('Fork created', 'success');
                        _pmbCloseModal();
                        await _pmbLoadAll();
                        _pmbRender();
                        if (result?.id) setTimeout(() => _pmbOpenPinDetail(result.id), 150);
                    } catch { toast('Could not fork prompt', 'error'); }
                    break;
                }
                case 'add-to-board': _pmbOpenBoardPicker(promptId); break;
                case 'open-add-board-from-picker': _pmbCloseModal(); setTimeout(() => _pmbOpenBoardSheet(), 160); break;
                case 'assign-board': {
                    try {
                        await api('/boards/' + boardId + '/pins', { method: 'POST', body: { prompt_id: promptId } });
                        const b = _pmbBoardById(boardId);
                        toast('Added to ' + (b ? b.name : 'board'), 'success');
                        if (b) b.pin_count = (b.pin_count || 0) + 1;
                        _pmbCloseModal();
                        _pmbRenderSidebar();
                    } catch { toast('Could not add to board', 'error'); }
                    break;
                }
                case 'unpin': {
                    try {
                        await api('/boards/' + _pmbState.boardId + '/pins/' + promptId, { method: 'DELETE' });
                        _pmbState.boardPins = _pmbState.boardPins.filter(p => p.id !== promptId);
                        const b = _pmbBoardById(_pmbState.boardId);
                        if (b) b.pin_count = Math.max(0, (b.pin_count || 1) - 1);
                        toast('Removed from board', 'success');
                        _pmbRenderMain(); _pmbRenderSidebar();
                    } catch { toast('Could not remove pin', 'error'); }
                    break;
                }
                case 'delete-prompt': {
                    const p = _pmbState.prompts.find(x => x.id === promptId);
                    if (!p) return;
                    if (!confirm('Delete "' + (p.title || 'this prompt') + '"? This cannot be undone.')) return;
                    try {
                        await api('/prompts/' + promptId, { method: 'DELETE' });
                        toast('Prompt deleted', 'success');
                        _pmbCloseModal();
                        await _pmbLoadAll();
                        if (_pmbState.view === 'board' && _pmbState.boardId) await _pmbGoBoard(_pmbState.boardId);
                        else _pmbRender();
                    } catch { toast('Could not delete prompt', 'error'); }
                    break;
                }
            }
        });
    }

    window.openBoardWorkspace = function() {
        if (!state.isPremium) {
            showPremiumModal();
            return;
        }
        const ws = $('#boardWorkspace');
        if (!ws) return;
        ws.classList.add('open');
        document.body.style.overflow = 'hidden';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'board'));
        _pmbState.view = 'feed'; _pmbState.boardId = null; _pmbState.activeTag = null; _pmbState.search = '';
        const input = $('#pmbSearchInput'); if (input) input.value = '';
        _pmbLoadAll().then(_pmbRender);
    };

    function closeBoardWorkspace() {
        _pmbCloseModal();
        $('#boardWorkspace')?.classList.remove('open');
        document.body.style.overflow = '';
        $$('.nav-item[data-view]').forEach(el => el.classList.toggle('active', el.dataset.view === 'library'));
    }

    function initBoardWorkspace() {
        const ws = $('#boardWorkspace');
        if (!ws) return;
        $('#closeBoardBtn')?.addEventListener('click', closeBoardWorkspace);
        $('#pmbAddPromptBtn')?.addEventListener('click', () => _pmbOpenPromptSheet(null, _pmbState.view === 'board' ? _pmbState.boardId : null));
        $('#pmbModalBackdrop')?.addEventListener('click', _pmbCloseModal);
        const searchInput = $('#pmbSearchInput');
        const searchClear = $('#pmbSearchClear');
        let searchTimer = null;
        searchInput?.addEventListener('input', e => {
            const val = e.target.value;
            searchClear?.classList.toggle('visible', val.length > 0);
            clearTimeout(searchTimer);
            searchTimer = setTimeout(() => { _pmbState.search = val; _pmbRenderMain(); }, 120);
        });
        searchInput?.addEventListener('keydown', e => {
            if (e.key === 'Escape') {
                searchInput.value = ''; searchInput.blur();
                _pmbState.search = '';
                searchClear?.classList.remove('visible');
                _pmbRenderMain();
            }
        });
        searchClear?.addEventListener('click', () => {
            searchInput.value = ''; _pmbState.search = '';
            searchClear.classList.remove('visible');
            searchInput.focus();
            _pmbRenderMain();
        });
        ws.addEventListener('keydown', e => {
            if (e.key !== 'Escape') return;
            const modal = $('#pmbModal');
            if (modal && !modal.hidden) _pmbCloseModal();
            else closeBoardWorkspace();
        });
    }
    /* ============================================================================
       SNIPPETS STORE
       Powers the prompt-editor side panel (search, insert-at-cursor, Quick-add).
       The standalone Snippets workspace was replaced by Quick Fill (2026-07).
       ls key: pl_snippets  →  [{id, title, category, content, created}]
       ============================================================================ */

    const SNIP_LS_KEY = 'pl_snippets';
    let _snipBlocks = [];

    function _snipLoad() {
        try {
            _snipBlocks = JSON.parse(localStorage.getItem(SNIP_LS_KEY) || '[]');
        } catch {
            _snipBlocks = [];
        }
    }

    function _snipSave() {
        localStorage.setItem(SNIP_LS_KEY, JSON.stringify(_snipBlocks));
    }

    function _snipUID() {
        return 'snip_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
    }

    // ── Starter templates ────────────────────────────────────────────────────────
    const SNIP_TEMPLATES = [{
            category: 'Signatures',
            title: 'Standard Email Sign-off',
            content: 'Best regards,\n[Your name]\n[Your title]'
        },
        {
            category: 'Disclaimers',
            title: 'AI-Generated Content Notice',
            content: 'This content was drafted with AI assistance and reviewed by a human before publishing.'
        },
        {
            category: 'Greetings',
            title: 'Warm Opening Line',
            content: 'Hope this finds you well — appreciate you taking the time to read this.'
        },
        {
            category: 'Closings',
            title: 'Call-to-Action Closer',
            content: "Let me know if you'd like to take this further — happy to jump on a call this week."
        },
        {
            category: 'Boilerplate',
            title: 'Confidentiality Notice',
            content: 'This message is intended only for the addressee and may contain confidential information. If received in error, please delete and notify the sender.'
        },
        {
            category: 'Other',
            title: 'Placeholder Bracket Reminder',
            content: '[Replace this bracketed text with your specific detail before sending.]'
        },
    ];

    function _snipSeedTemplates() {
        const seeded = localStorage.getItem('pl_snip_seeded');
        if (seeded) return;
        _snipBlocks = SNIP_TEMPLATES.map((t, i) => ({
            id: 'tpl_' + i + '_' + Math.random().toString(36).slice(2, 6),
            title: t.title,
            category: t.category,
            content: t.content,
            created: new Date().toISOString(),
        }));
        _snipSave();
        localStorage.setItem('pl_snip_seeded', '1');
    }

    // ── Modal side panel: insert snippet at cursor ──────────────────────────────
    function _snipPanelRefresh() {
        const list = $('#snipPanelList');
        if (!list) return;
        _snipSeedTemplates();
        _snipLoad();
        const query = ($('#snipPanelSearch')?.value || '').toLowerCase();
        const catBtn = document.querySelector('#snipPanelCats .chip.active');
        const cat = catBtn?.dataset?.cpf || 'all';

        let blocks = _snipBlocks;
        if (cat !== 'all') blocks = blocks.filter(b => b.category === cat);
        if (query) blocks = blocks.filter(b =>
            (b.title || '').toLowerCase().includes(query) ||
            (b.content || '').toLowerCase().includes(query));

        if (!blocks.length) {
            list.innerHTML = '<div style="color:var(--ink-3);font-size:var(--fs-sm);padding:var(--sp-3);text-align:center;">No snippets found.<br>Use Quick-add below to create one.</div>';
            return;
        }

        list.innerHTML = blocks.map(b =>
            '<div class="ctx-panel-item" data-spid="' + escapeAttr(b.id) + '" ' +
            'style="padding:8px var(--sp-3);cursor:pointer;border-bottom:1px solid var(--border,#374151);">' +
            '<div style="font-size:var(--fs-sm);font-weight:600;">' + escapeHtml(b.title) + '</div>' +
            '<div style="font-size:11px;color:var(--ink-3);">' + escapeHtml(b.category || 'Other') + '</div>' +
            '</div>'
        ).join('');

        list.querySelectorAll('[data-spid]').forEach(item => {
            item.addEventListener('click', () => {
                const block = _snipBlocks.find(b => b.id === item.dataset.spid);
                if (!block) return;
                const ta = $('#promptContent');
                if (ta) {
                    const ins = block.content || '';
                    const pos = ta.selectionStart ?? ta.value.length;
                    ta.value = ta.value.slice(0, pos) + ins + ta.value.slice(pos);
                    ta.selectionStart = ta.selectionEnd = pos + ins.length;
                    ta.dispatchEvent(new Event('input'));
                }
                toast('Snippet inserted', 'success');
            });
        });
    }

    function _snipPanelSaveNew() {
        const title = ($('#snipPanelNewTitle')?.value || '').trim();
        const category = $('#snipPanelNewCat')?.value || 'Other';
        const content = ($('#snipPanelNewContent')?.value || '').trim();
        if (!title) {
            toast('Give the snippet a title', 'warning');
            return;
        }
        if (!content) {
            toast('Add content to the snippet', 'warning');
            return;
        }
        _snipLoad();
        _snipBlocks.unshift({
            id: _snipUID(),
            title,
            category,
            content,
            created: new Date().toISOString()
        });
        _snipSave();
        if ($('#snipPanelNewTitle')) $('#snipPanelNewTitle').value = '';
        if ($('#snipPanelNewContent')) $('#snipPanelNewContent').value = '';
        const details = $('#snipPanelAddDetails');
        if (details) details.open = false;
        _snipPanelRefresh();
        toast('Snippet saved', 'success');
    }



    // Mask a licence key for display: keep the first 8 and last 4 chars.
    function _maskLicenceKey(k) {
        if (!k) return '';
        if (k.length <= 12) return k;
        return k.slice(0, 8) + '*'.repeat(Math.max(0, k.length - 12)) + k.slice(-4);
    }

    // Repaint the Settings > Licence Key panel from state. Safe to call any time.
    function refreshLicencePanel() {
        const box = $('#licenceStatus');
        const text = $('#licenceStatusText');
        const btn = $('#licenceActivateBtn');
        const input = $('#settingsLicenceKeyInput');
        const saveBtn = $('#licenceSaveDbBtn');
        const unsaveBtn = $('#licenceUnsaveDbBtn');
        if (!box || !text || !btn || !input) return;

        if (state.isPremium && state.licenceSavedToDb) {
            box.style.borderLeftColor = 'var(--success)';
            text.textContent = 'Licensed \u2014 Pro features unlocked';
            text.style.color = 'var(--success)';
            input.value = _maskLicenceKey(state.licenceKey);
            input.disabled = true;
            btn.disabled = true;
            btn.hidden = false;
            btn.innerHTML = '<span class="material-symbols-outlined">check</span> Activated';
            if (saveBtn) saveBtn.hidden = true;
            if (unsaveBtn) unsaveBtn.hidden = false;
        } else if (state.isPremium && !state.licenceSavedToDb) {
            box.style.borderLeftColor = 'var(--success)';
            text.textContent = 'Pro unlocked for this session \u2014 not saved to DB yet';
            text.style.color = 'var(--success)';
            input.value = _maskLicenceKey(state.licenceKey);
            input.disabled = true;
            btn.hidden = true;
            if (saveBtn) saveBtn.hidden = false;
            if (unsaveBtn) unsaveBtn.hidden = true;
        } else {
            box.style.borderLeftColor = 'var(--ink-3)';
            text.textContent = 'Not licensed \u2014 enter your key to unlock Pro features';
            text.style.color = 'var(--ink-3)';
            input.disabled = false;
            btn.disabled = false;
            btn.hidden = false;
            btn.innerHTML = '<span class="material-symbols-outlined">vpn_key</span> Activate Licence';
            if (saveBtn) saveBtn.hidden = true;
            if (unsaveBtn) unsaveBtn.hidden = true;
        }
    }

    function initLicenceUI() {
        const btn = $('#licenceActivateBtn');
        const input = $('#settingsLicenceKeyInput');
        const status = $('#licenceActivateStatus');
        if (!btn || !input || !status) return;

        const run = async () => {
            if (btn.disabled) return;
            const key = input.value.trim();
            if (!key) {
                status.textContent = 'Enter a licence key';
                status.style.color = 'var(--ink-3)';
                input.focus();
                return;
            }
            btn.disabled = true;
            status.textContent = 'Checking\u2026';
            status.style.color = 'var(--ink-3)';
            try {
                if (await _validateAndStoreKey(key)) {
                    status.textContent = 'Pro unlocked \u2014 thank you!';
                    status.style.color = 'var(--success)';
                    toast('Pro unlocked - thank you!', 'success');
                    refreshLicencePanel();
                } else {
                    status.textContent = 'Invalid licence key';
                    status.style.color = 'var(--danger)';
                    btn.disabled = false;
                }
            } catch (e) {
                status.textContent = 'Invalid licence key';
                status.style.color = 'var(--danger)';
                btn.disabled = false;
            }
        };

        btn.addEventListener('click', run);
        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                run();
            }
        });

        const saveBtn = $('#licenceSaveDbBtn');
        if (saveBtn) {
            saveBtn.addEventListener('click', async () => {
                saveBtn.disabled = true;
                status.textContent = 'Saving\u2026';
                status.style.color = 'var(--ink-3)';
                try {
                    await _saveLicenceKeyToDb();
                    status.textContent = 'Saved \u2014 licence will persist after restart';
                    status.style.color = 'var(--success)';
                    toast('Licence key saved', 'success');
                    refreshLicencePanel();
                } catch (e) {
                    status.textContent = 'Could not save licence key';
                    status.style.color = 'var(--danger)';
                    saveBtn.disabled = false;
                }
            });
        }

        const unsaveBtn = $('#licenceUnsaveDbBtn');
        if (unsaveBtn) {
            unsaveBtn.addEventListener('click', async () => {
                // Removing the persisted key is a one-way trip until the key is
                // re-entered and saved again -- require the user to type REMOVE
                // rather than acting on a single click.
                const typed = prompt('This removes your licence key from the database. It stays unlocked for this session but won\'t persist after restart.\n\nType REMOVE to confirm:');
                if (typed !== 'REMOVE') return;
                unsaveBtn.disabled = true;
                status.textContent = 'Removing\u2026';
                status.style.color = 'var(--ink-3)';
                try {
                    await _unsaveLicenceKeyFromDb();
                    status.textContent = 'Removed \u2014 no longer saved to DB';
                    status.style.color = 'var(--ink-3)';
                    toast('Licence key removed from DB', 'success');
                    refreshLicencePanel();
                } catch (e) {
                    status.textContent = 'Could not remove licence key';
                    status.style.color = 'var(--danger)';
                } finally {
                    unsaveBtn.disabled = false;
                }
            });
        }

        const widgetHeader = $('#licenceWidgetHeader');
        const widgetToggle = $('#licenceWidgetToggle');
        const widgetBody = $('#licenceWidgetBody');
        if (widgetHeader && widgetBody) {
            const applyCollapsed = (collapsed) => {
                widgetBody.classList.toggle('collapsed', collapsed);
                widgetHeader.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
                if (widgetToggle) {
                    const chev = widgetToggle.querySelector('.chev');
                    if (chev) chev.style.transform = collapsed ? 'rotate(-90deg)' : '';
                }
            };
            let collapsed = false;
            try {
                collapsed = localStorage.getItem('pl_licenceWidgetCollapsed') === '1';
            } catch (e) {}
            applyCollapsed(collapsed);
            widgetHeader.addEventListener('click', (e) => {
                if (e.target.closest('#settingsLicenceKeyInput')) return;
                collapsed = !widgetBody.classList.contains('collapsed');
                applyCollapsed(collapsed);
                try {
                    localStorage.setItem('pl_licenceWidgetCollapsed', collapsed ? '1' : '0');
                } catch (e) {}
            });
        }

        refreshLicencePanel();
    }

